var branchDialogueDefs={
  rosaWater:{npc:"rosa",kicker:"La fiebre de Iara",start:"start",nodes:{
    start:{lines:["Rosa no guarda el agua de inmediato. La acerca a los labios de su hija y espera a que la niña trague antes de mirar al grupo.","«Se llama Iara. Si abre los ojos y ve sus armas, va a creer que volvieron los de arriba.»"],options:[
      {label:"Bajar las armas y preguntarle qué vio",hint:"Convierte la ayuda en confianza real.",fx:{morale:1},psy:{empathy:1,stress:-1},flags:{askedIaraName:true},next:"trust"},
      {label:"Pedir primero la munición prometida",hint:"Mantiene el trato, pero enfría la escena.",fx:{ammo:1,morale:-1},psy:{pragmatism:1,empathy:-1},flags:{pressedRosaPayment:true},next:"cold"},
      {label:"Decir que deben seguir antes del rastreo",hint:"Corta la conversación y conserva tiempo.",fx:{threat:-1,morale:-1},psy:{pragmatism:1,stress:1},flags:{leftRosaQuickly:true}}
    ]},
    trust:{lines:["Rosa cubre el arma de Noa con una mano, no para apartarla, sino para enseñar el gesto a Iara.","«Vio una casa segura cerrarse desde afuera. No fue saqueo. Alguien marcó la puerta para que pareciera vacía.»"],options:[
      {label:"Preguntar qué marca abre esa puerta",hint:"Aprende una señal de cazadores.",archive:["hunterMarks"],fx:{threat:-1},psy:{empathy:1,pragmatism:1},flags:{rosaTaughtDoorMark:true},next:"route"},
      {label:"Prometer revisar la casa si sobreviven",hint:"Crea una deuda humana que pesará después.",fx:{morale:2,threat:1},psy:{empathy:2},flags:{promisedRosaHouse:true},next:"route"},
      {label:"Aclarar que no prometen rescates",hint:"Sostiene el límite del grupo.",fx:{morale:-1},psy:{pragmatism:1,empathy:-1},flags:{refusedRosaPromise:true},next:"route"}
    ]},
    cold:{lines:["Rosa deja dos cargadores en el suelo, lejos de la niña. No parece ofendida; parece acostumbrada a medir a la gente por lo que pide primero.","«La munición mata lejos. El agua mata de cerca cuando falta. Ya sabemos qué clase de miedo cargan ustedes.»"],options:[
      {label:"Devolver un cargador y pedir la ruta",hint:"Repara parte del gesto sin perder la información.",fx:{ammo:-1,morale:2,threat:-1},archive:["hunterMarks"],psy:{empathy:1},flags:{returnedRosaAmmo:true},next:"route"},
      {label:"Aceptar el juicio y guardar silencio",hint:"La relación queda útil, no cercana.",fx:{threat:-1},psy:{pragmatism:1},flags:{acceptedRosaColdTrade:true}},
      {label:"Responder que la niña no es la única en riesgo",hint:"Una verdad dura que rompe confianza.",fx:{morale:-3,threat:1},psy:{stress:2,empathy:-1},flags:{hurtRosaTrust:true}}
    ]},
    route:{lines:["Rosa dibuja tres líneas con agua sobre el polvo. Una desaparece de inmediato; las otras dos quedan brillando bajo la linterna.","«La que se borra es para la Red UNO. La que queda torcida es para gente viva. Si ven una tercera, no entren: alguien quiere que los vean entrando.»"],options:[
      {label:"Memorizar la ruta torcida",hint:"Gana una lectura táctica para superficie.",add:["routeMap"],fx:{threat:-2},archive:["hunterMarks"],psy:{pragmatism:1},flags:{rosaRouteLearned:true}},
      {label:"Acompañarla hasta la casa marcada",hint:"Abre un desvío narrativo con Rosa e Iara antes de volver a la ruta principal.",fx:{morale:2,threat:2},psy:{empathy:2,resolve:1},flags:{rosaEscortAccepted:true},routeScene:"rosaIaraRoute"},
      {label:"Borrar las tres marcas al salir",hint:"Protege la posición, pero corta su mensaje.",fx:{threat:-2,morale:-2},psy:{pragmatism:1,empathy:-1},flags:{erasedRosaMarks:true}}
    ]}
  }},
  liraBorder:{npc:"lira",kicker:"Frontera de golpes",start:"start",nodes:{
    start:{lines:["Lira golpea dos veces el hormigón y espera. Noa responde tarde; el tercer golpe de la merodeadora suena como una advertencia, no como un saludo.","«Si no entienden el ritmo, no inventen palabras. Aquí una mala respuesta despierta a los que no quieren hablar.»"],options:[
      {label:"Admitir que no conocen el código",hint:"La honestidad baja el riesgo social.",fx:{morale:1},psy:{empathy:1,stress:-1},flags:{admittedNoTapCode:true},next:"truth"},
      {label:"Pedir que nombre el límite",hint:"Busca reglas antes de avanzar.",fx:{threat:-1},psy:{pragmatism:1},flags:{askedLiraBoundary:true},next:"truth"},
      {label:"Decir que nadie les prohíbe pasar",hint:"La conversación puede romperse.",psy:{resolve:1,stress:1},flags:{challengedLiraBorder:true},next:"warning"}
    ]},
    truth:{lines:["«El límite no es el túnel. Es el pecho abierto de mi hermano. La Red UNO guarda su último mapa y ustedes pisan la ruta para recuperarlo.»","Lira no mira el arma de Sara. Mira la mochila, como si esperara ver ahí una parte de alguien."],options:[
      {label:"Preguntar si el núcleo conserva memoria",hint:"Abre el sentido ritual de los merodeadores.",archive:["coreRite"],fx:{morale:1},psy:{empathy:1},flags:{askedLiraCores:true},next:"memory"},
      {label:"Ofrecer tela para cerrar la herida",hint:"Gasta material y cambia el tono de la frontera.",reqItems:["cloth"],fx:{cloth:-1,morale:3,threat:-2},archive:["redEyes"],psy:{empathy:2},flags:{helpedLiraWound:true},next:"memory"},
      {label:"Pedir solo una ruta hacia la torre",hint:"La negociación queda seca.",fx:{threat:1},psy:{pragmatism:1,empathy:-1},flags:{askedLiraTowerOnly:true},next:"memory"}
    ]},
    warning:{lines:["Lira levanta la mano y las ópticas rojas aparecen entre columnas. Nadie dispara todavía.","«Entonces pasen como pasa la Red UNO: haciendo ruido y dejando cuerpos que otros tendrán que cargar.»"],options:[
      {label:"Bajar la voz y pedir una regla",hint:"Todavía puedes salvar el contacto.",fx:{morale:1,threat:-1},psy:{empathy:1,stress:-1},flags:{deescalatedLira:true},next:"truth"},
      {label:"Avanzar sin bajar las armas",hint:"El choque nace dentro del diálogo.",combat:{title:"Frontera rota",brief:"Los merodeadores interpretan el avance como una invasión y cierran el túnel.",encounters:[["merodeador2","merodeador4"],["merodeador","merodeador3"]],xp:36,canFlee:true},victory:{title:"Una frontera ensangrentada",result:"El grupo cruza, pero las marcas de los merodeadores desaparecen de las paredes cercanas.",fx:{threat:7,morale:-5},archive:["redEyes"],flags:{liraTalkBecameFight:true}},defeat:{title:"Expulsados del límite",result:"Los merodeadores los obligan a retroceder sin perseguir más allá de sus marcas.",fx:{threat:5,morale:-4},flags:{liraBorderLost:true}}},
      {label:"Retirarse sin responder",hint:"Evita la pelea y pierde la oportunidad.",fx:{threat:-1,morale:-2},psy:{pragmatism:1,resolve:-1},flags:{leftLiraBorder:true}}
    ]},
    memory:{lines:["«Un núcleo no es una llave. Es el último segundo de alguien: miedo, ruta, nombre, calor. Si lo abren como chatarra, la Red UNO aprende a abrirnos igual.»"],options:[
      {label:"Ayudar a Lira a recuperar el núcleo exiliado",hint:"Abre un desvío narrativo hacia el túnel donde la Red UNO guarda la memoria de su hermano.",fx:{morale:2,threat:2},archive:["coreRite"],psy:{empathy:2,resolve:1},flags:{liraTrust:true,liraRecoveryAccepted:true},routeScene:"liraExiledCore"},
      {label:"Pedir una ruta que no cruce sus muertos",hint:"Obtiene avance sin reclamar sus símbolos.",add:["routeMap"],fx:{threat:-1},psy:{pragmatism:1},flags:{liraSafeRoute:true}},
      {label:"Decir que todo puede ser recurso",hint:"La lógica de taller destruye la alianza.",fx:{morale:-5,threat:3},psy:{stress:2,empathy:-2,pragmatism:1},flags:{liraDistrust:true}}
    ]}
  }},
  matiasSaved:{npc:"matias",kicker:"Superviviente rescatado",start:"start",nodes:{
    start:{lines:["Matías respira contra el vendaje nuevo. Cuando Sara intenta levantarlo, él le toma la muñeca con una fuerza que no debería tener.","«No me salven si van a caminar como patrulla. La fiebre engaña a la Red UNO, pero la culpa no engaña a nadie.»"],options:[
      {label:"Preguntar qué escuchó en la fiebre",hint:"Busca la pista sin exigirle moverse.",archive:["matias"],fx:{morale:1},psy:{empathy:1},flags:{heardMatiasFever:true},next:"pattern"},
      {label:"Pedirle la ruta antes de cargarlo",hint:"Ordena prioridades bajo presión.",add:["routeMap"],psy:{pragmatism:1},flags:{matiasRoute:true},next:"pattern"},
      {label:"Decirle que guarde fuerzas",hint:"Cuida al herido, pero deja huecos en la información.",fx:{morale:1},psy:{empathy:1},flags:{protectedMatiasSilence:true},next:"pattern"}
    ]},
    pattern:{lines:["«La señal no nació en la torre. La empujaron desde soporte vital. Una mujer metió su voz entre órdenes viejas y la Red UNO la usa como contraseña sin saber que todavía piensa.»"],options:[
      {label:"Preguntar el nombre de la mujer",hint:"Aterriza la señal en una persona concreta.",archive:["origin"],fx:{threat:-1},psy:{empathy:1},flags:{knowsOperatorWord:true},next:"exit"},
      {label:"Preguntar qué ruta evita los semáforos",hint:"Mejora la lectura de superficie.",add:["routeMap"],fx:{threat:-2},psy:{pragmatism:1},flags:{matiasAvenueExit:true},next:"exit"},
      {label:"Interrumpirlo: solo sirve si puede caminar",hint:"La utilidad pesa más que el testimonio.",fx:{morale:-3,threat:-1},psy:{empathy:-1,pragmatism:1,stress:1},flags:{silencedMatias:true},next:"exit"}
    ]},
    exit:{lines:["Matías cierra los ojos cuando escucha botas lejos de la farmacia. No son de la Red UNO; son de gente buscando lo mismo que ustedes.","«Si me llevan, van más lento. Si me dejan, quizá todavía pueda mentir por radio cuando los busquen.»"],options:[
      {label:"Llevarlo de vuelta a Línea 1",hint:"Abre un desvío narrativo con riesgo, recompensa y salida tardía.",fx:{morale:3,threat:2},psy:{empathy:2,resolve:1},flags:{carriedMatias:true},routeScene:"matiasRescue"},
      {label:"Dejarle agua y un canal abierto",hint:"Lo conviertes en aliado de radio.",fx:{water:-1,morale:1,threat:-2},psy:{empathy:1,pragmatism:1},flags:{matiasRadioAlly:true},req:{water:1}},
      {label:"Usar su frecuencia y cerrar la puerta",hint:"Obtienes ventaja con costo moral.",fx:{morale:-4,threat:-3},psy:{pragmatism:1,empathy:-1},flags:{usedMatiasAsDecoy:true}}
    ]}
  }},
  matiasLeft:{npc:"matias",kicker:"Últimas indicaciones",start:"start",nodes:{
    start:{lines:["Matías empuja el mapa hacia Sara y no pregunta por qué no lo cargan. Esa cortesía hace más difícil mirarlo.","«No prometan volver si la promesa solo sirve para que ustedes duerman mejor.»"],options:[
      {label:"Prometer volver solo si hay ruta real",hint:"Una promesa honesta, no limpia.",fx:{morale:1},psy:{empathy:1,pragmatism:1},flags:{promisedMatiasIfPossible:true},next:"map"},
      {label:"Pedir la salida más corta",hint:"Acepta que el intercambio ya ocurrió.",fx:{threat:-1},psy:{pragmatism:1},flags:{askedMatiasShortestExit:true},next:"map"},
      {label:"Cerrar sin contestar",hint:"Termina el vínculo.",fx:{morale:-2,threat:-1},psy:{stress:1,empathy:-1},flags:{leftMatiasWithoutPromise:true}}
    ]},
    map:{lines:["«Cuando los semáforos prendan en rojo sin tránsito, no crucen. No regulan autos. Ordenan drones.»"],options:[
      {label:"Preguntar quién le enseñó eso",hint:"Abre una pista sobre cazadores y exiliados.",archive:["truce"],fx:{morale:1},psy:{empathy:1},flags:{matiasNamedTruce:true}},
      {label:"Copiar la ruta sobre tela",hint:"Asegura el dato si el cartón se moja.",add:["routeMap"],fx:{threat:-1},psy:{pragmatism:1},flags:{copiedMatiasMap:true}},
      {label:"Usar la ruta y no mirar atrás",hint:"Sobreviven más rápido, peor acompañados.",fx:{morale:-2,threat:-2},psy:{pragmatism:1,empathy:-1},flags:{leftMatiasBehindFast:true}}
    ]}
  }},
  unit7Protocol:{npc:"unit7",kicker:"Orden final",start:"start",nodes:{
    start:{lines:["La unidad S-7 no se va. El motor queda suspendido con un temblor pequeño, casi animal.","«Solicitud: orden final. El protocolo antiguo protege pulso humano. Defina humano.»"],options:[
      {label:"Responder: humano es quien puede negarse",hint:"Confunde el criterio de obediencia.",fx:{threat:-1,morale:1},psy:{resolve:1,empathy:1},flags:{unit7HumanRefusal:true},next:"define"},
      {label:"Responder con la frecuencia de la señal",hint:"Usa lenguaje de sistema.",fx:{threat:-2},archive:["sonar"],psy:{pragmatism:1},flags:{unit7Echo:true},next:"define"},
      {label:"Abrir el chasis antes de que transmita",hint:"La acción puede volverse combate sin aviso.",combat:{title:"Orden rechazada",brief:"El chasis interpreta la manipulación como captura y reactiva sus placas de defensa.",encounters:[["drone"],["drone","drone"]],xp:34,canFlee:true},victory:{title:"Memoria arrancada",result:"Elías extrae una ruta parcial antes de que el núcleo se queme.",fx:{threat:3,morale:-2},add:["routeMap"],archive:["sonar"],flags:{unit7ForcedOpen:true}},defeat:{title:"Identidad recuperada",result:"La unidad escapa con una lectura incompleta del grupo.",fx:{threat:10,morale:-3},flags:{unit7Escaped:true}}}
    ]},
    define:{lines:["«Negarse genera error. Error genera cuidado. Cuidado genera corrección.»","La ranura inferior se abre un poco más. Dentro no hay arma visible, solo una memoria tibia."],options:[
      {label:"Ayudar a S-7 a recuperar su orden original",hint:"Abre un desvío hacia la subestación donde la Red UNO sobrescribió su memoria.",fx:{morale:2,threat:2},archive:["sonar"],psy:{empathy:1,resolve:1},flags:{unit7RecoveryAccepted:true},routeScene:"unit7LastOrder"},
      {label:"Pedir su última ruta real",hint:"Obtiene mapa, pero deja huella técnica.",add:["routeMap"],fx:{threat:1},psy:{pragmatism:1},flags:{unit7Route:true}},
      {label:"Ordenarle que se apague",hint:"Evita transmisión y carga una decisión dura.",fx:{morale:-2,threat:-3},psy:{resolve:1,stress:1},flags:{unit7Silenced:true}}
    ]}
  }},
  varelaArchives:{npc:"elder",kicker:"Memoria del consejo",start:"start",nodes:{
    start:{lines:["Varela les hace sitio junto a la lámpara. Sara deja la hoja de los exiliados sobre la mesa. «Esto también lo tenían cuando nos pidieron seguir la señal». El anciano acerca el papel para leerlo.","«Sí. Y debimos explicárselo antes de mandarlos». Noa sigue de pie. Varela señala la silla libre, pero no insiste cuando ella no se sienta."],options:[
      {label:"Preguntar por qué ocultaron a los exiliados",hint:"Pide una explicación por la información que les negaron.",archive:["exiles"],fx:{morale:1},psy:{resolve:1},flags:{varelaNamedCouncilLie:true},next:"debt"},
      {label:"Pedir solo lo necesario para sobrevivir",hint:"Prioriza la misión sin abrir todo el conflicto.",fx:{threat:-1},psy:{pragmatism:1},flags:{varelaPracticalBrief:true},next:"debt"},
      {label:"Decir que el consejo ya eligió por todos",hint:"La respuesta rompe confianza con los ancianos.",fx:{morale:-2},psy:{stress:1,resolve:1},flags:{varelaCouncilChallenged:true},next:"debt"}
    ]},
    debt:{lines:["Varela abre una carpeta de fotografías. En una de ellas se ve a varias personas junto a un andén. «Vivían aquí. Trajeron tecnología de El Valle y quisieron usarla en sus propios cuerpos. El consejo de entonces los expulsó».","«Después dejamos de contar esa parte. Era más fácil pedirles a los jóvenes que salieran si creían que afuera solo había animales y máquinas». Sara le pregunta si él siguió contándolo así. «Sí», responde Varela."],options:[
      {label:"Preguntar quién dio la orden de expulsión",hint:"Recupera una pieza incómoda del origen.",archive:["protocol"],fx:{morale:1,threat:1},psy:{resolve:1},flags:{askedExpulsionOrder:true},next:"charge"},
      {label:"Pedir nombres, no culpas",hint:"Sostiene la memoria sin dividir al refugio todavía.",archive:["names"],fx:{morale:2},psy:{empathy:1},flags:{askedVarelaNames:true},next:"charge"},
      {label:"Cerrar la carpeta y salir",hint:"Evita cargar más contexto antes de la expedición.",fx:{threat:-1,morale:-1},psy:{pragmatism:1,empathy:-1},flags:{closedElderArchive:true}}
    ]},
    charge:{lines:["Varela separa las listas de nombres de los protocolos. «Pueden llevar copia de lo que lean. No tengo aquí un acta que diga quién firmó la expulsión». Elías anota qué documento falta. Noa mueve la lámpara para que puedan seguir leyendo.","Antes de cerrar, Varela deja sobre la hoja una ficha oxidada para que no se doble. Tiene una marca de UNO casi borrada. «Si encuentran a quien habla, pregúntenle qué necesita. Y no den por cierto todo lo que venga de una voz conocida. Tampoco de la mía»."],options:[
      {label:"Prometer investigar quién envió la señal",hint:"Refuerza propósito y cohesión.",fx:{morale:3},psy:{resolve:1,empathy:1},flags:{vowedSignalSource:true}},
      {label:"Pedir una advertencia concreta",hint:"Gana una lectura útil contra protocolos viejos.",fx:{threat:-2},archive:["signal"],psy:{pragmatism:1},flags:{elderWarning:true}},
      {label:"Guardar la ficha sin prometer nada",hint:"Acepta la ficha sin comprometerse a una respuesta.",fx:{morale:-1,threat:-1},psy:{pragmatism:1},flags:{keptVarelaTokenQuiet:true}}
    ]}
  }},
  unit12Sweep:{npc:"unit12",kicker:"Rastreo de altura",start:"start",nodes:{
    start:{lines:["La Unidad H-12 queda suspendida sobre la avenida como una campana negra. El altavoz no grita; ordena con la paciencia de una máquina acostumbrada a ser obedecida.","«Permanezcan visibles. La invisibilidad civil será tratada como sabotaje. La Red UNO agradece su cooperación.»"],options:[
      {label:"Pedir a Elías que mida el retraso",hint:"Busca una falla técnica antes de responder.",fx:{threat:-1},psy:{pragmatism:1},flags:{measuredH12Lag:true},next:"lag"},
      {label:"Responder con una identidad falsa",hint:"Usa el error como máscara.",fx:{threat:-2},archive:["sonar"],psy:{pragmatism:1},flags:{answeredH12WithGhost:true},next:"lag"},
      {label:"Gritar que no son ciudadanos de la Red UNO",hint:"Descarga rabia, pero deja una identidad fácil de rastrear.",fx:{morale:1,threat:3},psy:{stress:2,resolve:1},flags:{defiedH12Aloud:true},next:"warning"}
    ]},
    lag:{lines:["Elías levanta dos dedos. La voz llega antes que el giro de los sensores; durante medio segundo, la orden y el ojo no pertenecen al mismo cuerpo.","«Inconsistencia aceptable. Repita estado: visible, útil, corregible.»"],options:[
      {label:"Decir visible no significa obediente",hint:"La respuesta contamina la clasificación.",fx:{morale:2,threat:-1},psy:{resolve:1},flags:{h12VisibleNotObedient:true},next:"route"},
      {label:"Pedir que escolte una identidad vacía",hint:"Convierte el dron en señuelo breve.",fx:{threat:-4},psy:{pragmatism:1},flags:{h12EscortedGhost:true},next:"route"},
      {label:"Intentar forzar su núcleo en vuelo",hint:"Puede convertir el diálogo en combate.",combat:{title:"Rastreo quebrado",brief:"La Unidad H-12 interpreta la intrusión como sabotaje y llama drones menores desde la azotea.",encounters:[["drone","drone"],["drone","drone","drone"]],xp:48,canFlee:true},victory:{title:"Cielo sin altavoz",result:"El dron de rastreo cae lejos de la avenida y su memoria conserva una ruta de vuelo hacia la torre.",fx:{threat:4,morale:1},add:["droneCore"],archive:["sonar"],flags:{h12ShotDown:true}},defeat:{title:"Marcados por altura",result:"La unidad asciende con una lectura limpia de los tres supervivientes.",fx:{threat:14,morale:-4},flags:{h12MarkedGroup:true}}}
    ]},
    warning:{lines:["El dron tarda demasiado en responder. Cuando lo hace, la voz ya no usa el tono civil.","«La emoción no registrada aumenta probabilidad de contagio social. Recomiende aislamiento.»"],options:[
      {label:"Callar y dejar que la identidad falsa hable",hint:"Recupera control después del impulso.",fx:{threat:-2,morale:-1},psy:{pragmatism:1,stress:-1},flags:{recoveredFromH12Defiance:true},next:"route"},
      {label:"Sostener la provocación",hint:"La escena se rompe hacia combate.",combat:{title:"Aislamiento aéreo",brief:"El dron de rastreo desciende y abre fuego para fijar al grupo en la avenida.",encounters:[["drone","drone"],["drone"]],xp:42,canFlee:true},victory:{title:"Orden en el suelo",result:"El altavoz chisporrotea una última instrucción antes de apagarse.",fx:{threat:5,morale:2},add:["droneCore"],flags:{h12DefiedAndDropped:true}},defeat:{title:"Avenida cerrada",result:"El grupo escapa por una boca de metro mientras el rastreo reclama la calle.",fx:{threat:12,morale:-5},flags:{h12ClosedAvenue:true}}},
      {label:"Retirarse bajo la marquesina",hint:"Evita pelear y pierde la ventana.",fx:{threat:1,morale:-2},psy:{stress:-1,resolve:-1},flags:{hidFromH12:true}}
    ]},
    route:{lines:["La luz cyan del rastreo se desvía hacia una torre equivocada. Por primera vez, una máquina de la Red UNO protege una mentira humana.","«Ruta civil no encontrada. Registrando ausencia.»"],options:[
      {label:"Seguir la ausencia hasta el repetidor",hint:"Abre un desvío para descubrir qué cuerpos conserva H-12 en su mapa de vigilancia.",fx:{morale:2,threat:2},archive:["sonar"],psy:{empathy:1,resolve:1},flags:{h12RelayAccepted:true},routeScene:"unit12InvisibleMap"},
      {label:"Guardar el eco para Irene",hint:"La señal gana una pieza técnica.",archive:["sonar"],fx:{morale:1},psy:{empathy:1},flags:{h12EchoForIrene:true}},
      {label:"Borrar el rastro al cruzar",hint:"Protege al grupo, pero desperdicia información.",fx:{threat:-2,morale:-1},psy:{pragmatism:1},flags:{erasedH12Track:true}}
    ]}
  }},
  trackerCredential:{npc:"tracker",kicker:"Control de identidad",start:"start",nodes:{
    start:{lines:["El Rastreador Vega no mira la credencial: mira las manos de Sara, el respirador de Elías y la forma en que Noa calcula salidas.","«Los documentos mienten mal. Los cuerpos mienten mejor. Digan qué son antes de que mi equipo lo decida por ustedes.»"],options:[
      {label:"Responder: técnicos de continuidad",hint:"Sostiene la mentira oficial.",fx:{threat:-1},psy:{pragmatism:1},flags:{claimedContinuityTechs:true},next:"audit"},
      {label:"Responder: supervivientes en tránsito",hint:"Arriesga verdad parcial.",fx:{morale:1,threat:1},psy:{resolve:1},flags:{toldVegaTransitTruth:true},next:"audit"},
      {label:"Preguntar qué cuerpo está buscando",hint:"Devuelve el interrogatorio.",archive:["sonar"],psy:{pragmatism:1},flags:{askedVegaTarget:true},next:"audit"}
    ]},
    audit:{lines:["Vega acerca un lector al pecho de Noa. La pantalla no muestra nombres; muestra deuda, pulso y probabilidad de obediencia.","«Tres personas identificadas. Una coincide con archivo muerto. Una no debería haber salido del refugio. Una ya fue escuchada por la señal.»"],options:[
      {label:"Pedir que corrija el archivo muerto",hint:"Abre una contradicción administrativa.",fx:{threat:-2},archive:["names"],psy:{pragmatism:1},flags:{vegaCorrectedDeadFile:true},next:"break"},
      {label:"Decir que la señal eligió cuerpos vivos",hint:"Convierte el control en disputa moral.",fx:{morale:2,threat:1},psy:{resolve:1,empathy:1},flags:{vegaHeardSignalClaim:true},next:"break"},
      {label:"Empujar el lector lejos",hint:"Puede iniciar combate desde la conversación.",combat:{title:"Control roto",brief:"Vega retrocede y la escolta interpreta el gesto como agresión contra protocolo.",encounters:[["agent3","agent2"],["agent3","drone"],["agent2","drone"]],xp:50,canFlee:true},victory:{title:"Identidad arrancada",result:"El grupo destruye el lector antes de que suba el registro completo.",fx:{threat:6,morale:1},archive:["sonar"],flags:{vegaReaderDestroyed:true}},defeat:{title:"Identidades comprometidas",result:"La patrulla transmite una lectura parcial antes de que el grupo escape.",fx:{threat:15,morale:-5},flags:{signaturesKnown:true}}}
    ]},
    break:{lines:["El lector termina de comparar al grupo, pero no se apaga. El guante de Vega detecta una cuarta identidad y proyecta su propio rostro bajo un registro de fallecimiento.","Vega corta la transmisión con una mano temblorosa. «Ese pulso es mío. El expediente está debajo del cruce. Si la Red UNO reutilizó mi nombre, necesito saber cuántos más siguen caminando como muertos.»"],options:[
      {label:"Seguir la cuarta identidad hasta el registro",hint:"Abre un desvío para descubrir cómo la Red UNO reutiliza las identidades de muertos y exiliados.",fx:{morale:2,threat:2},archive:["names","sonar"],psy:{empathy:1,resolve:1},flags:{vegaFourthSignatureFound:true},routeScene:"vegaDeadNames"},
      {label:"Preguntar por los cascos morados",hint:"Gana contexto del cordón de Ortega.",archive:["purpleHelmets"],fx:{morale:1},psy:{resolve:1},flags:{vegaWarnedOrtega:true}},
      {label:"Advertirle que también está archivado",hint:"Golpea su seguridad y sube riesgo.",fx:{morale:1,threat:3},psy:{resolve:1,stress:1},flags:{vegaThreatenedWithArchive:true}}
    ]}
  }},
  ortegaLine:{npc:"commander",kicker:"Cordón morado",start:"start",nodes:{
    start:{lines:["Ortega examina el registro que acaba de aceptar el lector. Mantiene el arma baja, pero los soldados de la puerta esperan su señal.","«Este nombre figura como expulsado. El lector lo acepta; mi orden dice que no lo deje pasar. ¿De dónde sacaron el registro?»"],options:[
      {label:"Señalar que el lector aceptó el registro",hint:"Usa la ley contra la Red UNO.",fx:{threat:-1},archive:["purpleHelmets"],psy:{pragmatism:1},flags:{showedOrtegaProtocolGap:true},next:"doctrine"},
      {label:"Decir que Lira sigue viva",narrativeRequires:{all:["savedMerodeadora"],none:["liraDead","tookLivingCore","betrayedLira"]},hint:"Vuelve personal la contradicción.",fx:{morale:2,threat:1},psy:{empathy:1,resolve:1},flags:{toldOrtegaLiraLives:true},next:"doctrine"},
      {label:"Pedir paso sin discutir el archivo",hint:"Busca resultado rápido.",fx:{threat:1},psy:{pragmatism:1},flags:{askedOrtegaFastPass:true},next:"doctrine"}
    ]},
    doctrine:{lines:["Ortega levanta la visera. Detrás de él, alguien golpea una persiana cerrada. Mira hacia el ruido y vuelve a bajar la voz.","«Hay familias viviendo detrás de esa puerta. Me ordenaron mantenerlas dentro. Si abro sin autorización, vienen a reemplazarme. Y no sé qué harán con ellas.»"],options:[
      {label:"Preguntar cuánto de la ciudad queda ahí",hint:"Lo obliga a nombrar la ruina.",archive:["protocol"],fx:{morale:1},psy:{resolve:1},flags:{askedOrtegaCityCost:true},next:"breach"},
      {label:"Preguntar si las familias pueden negarse a quedarse",hint:"Eleva moral y tensión.",fx:{morale:3,threat:2},psy:{resolve:2},flags:{challengedOrtegaDoctrine:true},next:"breach"},
      {label:"Ofrecer borrar la ruta de Lira si abre paso",narrativeRequires:{any:["liraSafeRoute","liraTowerRoute","liraAlliance"],none:["liraDead"]},hint:"Una negociación oscura con costo moral.",fx:{threat:-4,morale:-4},psy:{pragmatism:1,empathy:-1},flags:{offeredToEraseLira:true},next:"breach"}
    ]},
    breach:{lines:["El comandante consulta el canal interno. Las puertas no se abren del todo; apenas lo suficiente para que el grupo decida si cruza como excepción o como amenaza.","«Puedo dejarlos entrar conmigo. No toquen los controles ni se separen. Si rechazan la custodia, tendrán que salir del perímetro.»"],options:[
      {label:"Entrar al barrio bajo custodia de Ortega",hint:"Abre un desvío narrativo para descubrir qué protege realmente la disciplina del cordón morado.",fx:{morale:2,threat:1},archive:["purpleHelmets"],psy:{empathy:1,resolve:1},flags:{ortegaDistrictAccepted:true},routeScene:"ortegaObedientCity"},
      {label:"Declararse enemigos de la Red UNO",hint:"Puede convertir la conversación en combate.",combat:{title:"Error declarado",brief:"Ortega cierra el puño y el cordón morado abre fuego antes de que la puerta termine de cerrarse.",encounters:[["agent4","agent2"],["agent4","agent3","agent2"]],xp:62,canFlee:true},victory:{title:"Cordón quebrado",result:"El perímetro cae y deja un acceso brutal hacia la torre.",fx:{threat:12,morale:5},archive:["purpleHelmets"],flags:{purpleLineBroken:true,towerEntered:true}},defeat:{title:"Archivados por fuerza",result:"El grupo se salva por una galería lateral, pero la torre registra su llegada.",fx:{threat:14,morale:-7},flags:{purpleDetour:true}}},
      {label:"Usar la excepción para entrar sin hablar más",hint:"Avanza con frialdad y baja exposición.",fx:{threat:-2,morale:-1},psy:{pragmatism:1},flags:{usedOrtegaException:true}}
    ]}
  }},
  veraRoutePrice:{npc:"vera",kicker:"El precio de la ruta",start:"start",nodes:{
    start:{lines:["Vera revisa el mapa sin tocarlo. Sus ojos siguen las curvas falsas, las verdaderas y las que nadie se atreve a dibujar.","«Una ruta no cuesta por lo que mide. Cuesta por la gente que queda expuesta cuando alguien la usa.»"],options:[
      {label:"Preguntar qué comunidad está comprando",hint:"Desnuda la lógica del trato.",archive:["hunterMarks"],fx:{morale:1},psy:{empathy:1},flags:{askedVeraWhoPays:true},next:"ledger"},
      {label:"Defender que el mapa protege a los débiles",hint:"Sostiene una mentira útil si ya la usaste.",fx:{morale:2,threat:1},psy:{resolve:1},flags:{defendedFalseRoute:true},next:"ledger"},
      {label:"Pedir el módulo y cerrar el trato",hint:"Prioriza el objetivo técnico.",fx:{threat:-1},psy:{pragmatism:1},flags:{askedVeraForModule:true},next:"ledger"}
    ]},
    ledger:{lines:["La jefa cosechadora gira una libreta cubierta de nombres. Algunos están tachados con tinta, otros con tierra seca.","«Yo vendo comida, no inocencia. Si quieren una salida limpia, vinieron tarde al fin del mundo.»"],options:[
      {label:"Ofrecer reparar una bomba por el módulo",hint:"Cambia deuda por trabajo.",fx:{scrap:-1,morale:2,threat:-2},req:{scrap:1},psy:{pragmatism:1,empathy:1},flags:{veraWorkTrade:true},next:"route"},
      {label:"Invocar la deuda de Rosa y los cazadores",hint:"La comunidad pesa más que la mercancía.",fx:{morale:3,threat:-1},psy:{empathy:1},flags:{veraHonorsHunterDebt:true},next:"route"},
      {label:"Aceptar que alguien pagará el costo",hint:"La honestidad es útil, pero fría.",fx:{morale:-2,threat:-2},psy:{pragmatism:1,empathy:-1},flags:{acceptedVeraCost:true},next:"route"}
    ]},
    route:{lines:["Vera deja el módulo en la mesa y apaga la lámpara que iluminaba el mapa. En la oscuridad, solo quedan visibles los puntos marcados con fósforo.","«Si traen verdad, no la entreguen completa al primer grupo hambriento. El hambre también aprende a gobernar.»"],options:[
      {label:"Prometer que la verdad no será mercancía",hint:"Refuerza la línea moral del grupo.",fx:{morale:3},psy:{resolve:1,empathy:1},flags:{truthNotForSale:true}},
      {label:"Pedir una ruta que no venda refugios",hint:"Obtiene salida con menos amenaza.",add:["routeMap"],fx:{threat:-3},psy:{pragmatism:1},flags:{veraCleanRoute:true}},
      {label:"Aceptar comida a cambio de silencio parcial",hint:"Gana recursos con costo ético.",fx:{food:2,morale:-4,threat:-1},psy:{pragmatism:1,empathy:-1},flags:{veraBoughtSilence:true}}
    ]}
  }},
  liraWounded:{npc:"lira",kicker:"Corazón abierto",start:"start",nodes:{
    start:{lines:["Lira despierta con el núcleo azul vibrando entre costillas y cable. Lo primero que hace no es buscar su arma: intenta cubrir la luz con la mano.","«Me llamaban Eliana antes del destierro. Lira fue el nombre que sobrevivió arriba.»"],options:[
      {label:"Usar el nombre Eliana",hint:"Reconoce su origen antes de pedir nada.",fx:{morale:2,threat:-1},psy:{empathy:2},flags:{calledLiraEliana:true},next:"valley"},
      {label:"Preguntar por El Valle",hint:"Busca la verdad detrás del destierro.",archive:["exiles"],psy:{pragmatism:1},flags:{askedLiraValley:true},next:"valley"},
      {label:"Mirar el núcleo antes que a ella",hint:"La relación empieza rota.",fx:{morale:-2,threat:1},psy:{empathy:-1,pragmatism:1},flags:{lookedAtLiraCore:true},next:"valley"}
    ]},
    valley:{lines:["«El Valle no curó a nadie gratis. Nos dio pulmones para respirar veneno y después cobró el aire con obediencia.»","La imagen proyectada muestra niños con prótesis aprendiendo a caminar bajo cámaras de la Red UNO."],options:[
      {label:"Preguntar cómo sacar gente de allí",hint:"La conversación apunta a rescate futuro.",fx:{morale:2},archive:["exiles"],psy:{empathy:1,resolve:1},flags:{askedValleyEscape:true},next:"core"},
      {label:"Pedir una ruta hacia la torre",hint:"Concreta la ayuda sin prometer alianza.",add:["routeMap"],fx:{threat:1},psy:{pragmatism:1},flags:{liraTowerRoute:true},next:"core"},
      {label:"Decir que el refugio tenía razón en temerlos",hint:"La herida social se abre otra vez.",fx:{morale:-4,threat:2},psy:{stress:2,empathy:-1},flags:{validatedExileFear:true},next:"core"}
    ]},
    core:{lines:["«Si toman mi núcleo, abren una puerta. Si lo dejan conmigo, quizá abran otra clase de puerta.»"],options:[
      {label:"Dejar el núcleo y pedir una señal de paso",hint:"La alianza queda viva.",fx:{morale:3,threat:-3},archive:["coreRite"],psy:{empathy:1},flags:{liraTrust:true,savedMerodeadora:true}},
      {label:"Pedir prestada una memoria parcial",hint:"Obtiene tecnología sin matarla, con riesgo.",add:["pulseCore"],fx:{threat:2,morale:1},psy:{pragmatism:1},flags:{borrowedLiraPulse:true}},
      {label:"Exigir el núcleo completo",hint:"La ayuda se convierte en abuso.",fx:{morale:-8,threat:4},add:["droneCore"],psy:{stress:2,empathy:-2},flags:{betrayedLira:true}}
    ]}
  }},
  operatorLive:{npc:"operator",kicker:"La voz de la señal",start:"start",nodes:{
    start:{lines:["Irene abre los ojos como si despertara dentro de una frase que lleva años repitiendo.","«No digan que me encontraron. Digan que alguien sostuvo la puerta desde adentro.»"],options:[
      {label:"Preguntar a quién hay que avisar primero",hint:"Ordena la transmisión desde las personas.",archive:["names"],fx:{morale:1},psy:{empathy:1},flags:{operatorPriorities:true},next:"names"},
      {label:"Pedir una ventana limpia de salida",hint:"Prioriza sobrevivir a la revelación.",fx:{threat:-2},psy:{pragmatism:1},flags:{operatorWindowAsked:true},next:"names"},
      {label:"Decir que emitirán todo sin filtro",hint:"La verdad sale fuerte y peligrosa.",fx:{morale:2,threat:3},psy:{resolve:1,stress:1},flags:{operatorFullTruthFirst:true},next:"names"}
    ]},
    names:{lines:["«Hay refugios que no saben que son refugios. Familias que creen vivir escondidas cuando en realidad fueron archivadas como población diferida.»"],options:[
      {label:"Pedir la lista de refugios diferidos",hint:"Gana archivo clave.",archive:["names"],fx:{threat:1},psy:{pragmatism:1},flags:{operatorNamesCopied:true},next:"choice"},
      {label:"Preguntar por los exiliados",hint:"Une la señal con El Valle.",archive:["exiles"],fx:{morale:1},psy:{empathy:1},flags:{operatorNamedExiles:true},next:"choice"},
      {label:"Pedir que oculte nombres vulnerables",hint:"Protege a algunos y limita la verdad.",fx:{threat:-3,morale:-1},psy:{pragmatism:1},flags:{operatorFilteredNames:true},next:"choice"}
    ]},
    choice:{lines:["La antena vibra. Irene ya no mira a Sara ni a Elías; mira a Noa, como si la cazadora fuera la única capaz de disparar contra una mentira sin matar a nadie.","«Elijan el peso. Nombre, ruta u orden. No cabe todo en una sola transmisión limpia.»"],options:[
      {label:"Transmitir primero los nombres",hint:"La memoria humana manda.",fx:{morale:3,threat:2},archive:["names"],psy:{empathy:1},flags:{transmittedNamesFirst:true}},
      {label:"Transmitir primero rutas seguras",hint:"La supervivencia inmediata manda.",fx:{threat:-4,morale:1},add:["routeMap"],psy:{pragmatism:1},flags:{transmittedRoutesFirst:true}},
      {label:"Transmitir las órdenes de la Red UNO",hint:"La acusación política manda.",fx:{morale:2,threat:4},archive:["protocol"],psy:{resolve:1},flags:{transmittedOrdersFirst:true}}
    ]}
  }},
  operatorDisconnect:{npc:"operator",kicker:"Última conversación",start:"start",nodes:{
    start:{lines:["Irene sonríe apenas cuando la copia termina. El soporte vital reduce la luz como si también entendiera que esto no es reparación.","«Gracias por no dejarme como máquina. Ahora no me pidan permiso para hacer lo que ya decidieron.»"],options:[
      {label:"Preguntar qué nombre salvar primero",hint:"Recupera prioridad antes del final.",archive:["names"],fx:{morale:1},psy:{empathy:1},flags:{operatorPriorities:true},next:"last"},
      {label:"Pedir una ruta de salida",hint:"Acepta su último acceso técnico.",fx:{threat:-2},psy:{pragmatism:1},flags:{operatorExitRoute:true},next:"last"},
      {label:"Desconectar sin más preguntas",hint:"Cumple con dureza y termina la conversación.",fx:{morale:-2,threat:-1},psy:{resolve:1,stress:1},flags:{operatorQuietEnd:true}}
    ]},
    last:{lines:["«Si alguien pregunta quién me mató, digan la verdad completa: la Red UNO me mantuvo viva para usarme, y ustedes me dejaron morir para que pudiera responder.»"],options:[
      {label:"Prometer llevar su nombre",hint:"Convierte el acto en memoria.",fx:{morale:3},archive:["origin"],psy:{empathy:1},flags:{operatorNameRemembered:true}},
      {label:"Prometer llevar sus pruebas",hint:"Convierte el acto en evidencia.",fx:{threat:-2},archive:["protocol"],psy:{pragmatism:1},flags:{operatorEvidenceRemembered:true}},
      {label:"No prometer nada que no controlan",hint:"Honestidad fría.",fx:{morale:-1,threat:-1},psy:{pragmatism:1,empathy:-1},flags:{operatorNoPromise:true}}
    ]}
  }}
};
var routeNarrativeDefs={
  matiasRescue:{title:"Desvío de Matías",endLoc:"Línea 1",combatResult:"El ruido obliga al grupo a defender la camilla antes de llegar al refugio.",defaultChoice:0,scenes:[
    {kicker:"Desvío de ruta · Farmacia del enlace",title:"Matías bajo el mostrador",image:"narrative/matias/matias-01-farmacia.webp",timeLimit:17000,lines:[
      "La farmacia queda en silencio cuando Sara termina el vendaje. Matías no pesa como un cuerpo: pesa como una decisión que ya no cabe en el mapa.",
      "Elías revisa la frecuencia que el herido aprieta contra el pecho. Noa mira la puerta. Afuera, la Red UNO sigue moviendo sus rastreos de señal como si la ciudad respirara por turnos."
    ],options:[
      {label:"Armar una camilla improvisada",hint:"Mueve a Matías con cuidado y conserva la promesa de rescate.",fx:{morale:2,threat:1},psy:{empathy:1,pragmatism:1},flags:{matiasStretcher:true},nextScene:1},
      {label:"Pedirle la ruta antes de levantarlo",hint:"Obtiene una pista táctica, pero alarga la exposición.",fx:{threat:1},add:["routeMap"],archive:["matias"],psy:{pragmatism:1},flags:{matiasRouteBeforeLift:true},nextScene:1},
      {label:"Salir de inmediato con él",hint:"Gana tiempo al costo de moverse con menos preparación.",fx:{morale:1,threat:3},psy:{resolve:1,stress:1},flags:{matiasRushedExit:true},nextScene:1}
    ]},
    {kicker:"Desvío de ruta · Túnel quieto",title:"El cielo no hace ruido",image:"narrative/matias/matias-02-tunel.webp",timeLimit:14500,lines:[
      "El regreso no parece una huida. Parece una operación hecha con respiraciones medidas. Cada paso de la camilla levanta agua negra entre los rieles.",
      "Arriba, donde el túnel se abre hacia la superficie, tres luces rojas permanecen quietas. Matías murmura sin abrir los ojos: «cuando el cielo parezca quieto, no crucen como vivos»."
    ],options:[
      {label:"Cruzar lento y enfriar la fiebre",hint:"Gasta agua para ocultar el pulso térmico de Matías.",cost:"Agua −1",req:{water:1},fx:{water:-1,threat:-3,morale:1},psy:{empathy:1,pragmatism:1},flags:{matiasFeverHidden:true},nextScene:2},
      {label:"Apagar señales con una batería",hint:"Elías fuerza una zona muda alrededor de la camilla.",cost:"Batería −1",req:{battery:1},fx:{battery:-1,threat:-5},psy:{pragmatism:2},flags:{matiasSignalMasked:true},nextScene:2},
      {label:"Correr antes del rastreo",hint:"El ruido puede convertir el rescate en combate.",cost:"Combate",fx:{morale:1,threat:3},psy:{resolve:1,stress:1},flags:{matiasNoisyCrossing:true},combat:{title:"Rastreo de fiebre",brief:"Los drones detectan el pulso alterado de Matías y bajan al túnel antes de que la camilla alcance la curva.",encounters:[["drone"],["drone","drone"]],xp:36,canFlee:true},victory:{title:"El cielo queda atrás",result:"El grupo derriba los drones el tiempo justo para sacar a Matías del túnel. La Red UNO pierde la lectura, pero el ruido deja una cicatriz en la ruta.",fx:{threat:4,morale:2},archive:["sonar"],flags:{matiasDroneAmbushWon:true}},nextScene:2}
    ]},
    {kicker:"Desvío de ruta · Enfermería Línea 1",title:"La advertencia de Matías",image:"narrative/matias/matias-03-enfermeria.webp",timeLimit:19000,lines:[
      "Matías queda en la enfermería del refugio, febril pero vivo. La expedición sale más tarde. La Red UNO ya cambió algunos rastreos de señal, pero Matías dejó una advertencia grabada: no crucen cuando el cielo parezca quieto.",
      "Antes de perder otra vez la conciencia, empuja tres cosas hacia Sara: una ampolla sellada, una frecuencia marcada con pulso febril y un mapa húmedo de República. No puede entregar todo; apenas puede sostener la mano."
    ],options:[
      {label:"Aceptar la ampolla sellada",hint:"Recupera medicina para compensar el rescate.",fx:{meds:1,morale:1},psy:{empathy:1},flags:{matiasAtRefuge:true,matiasLateStart:true,matiasRewardMeds:true},end:true},
      {label:"Aceptar la frecuencia de fiebre",hint:"Convierte su advertencia en ventaja contra futuros rastreos.",fx:{threat:-4,morale:1},archive:["sonar"],psy:{pragmatism:1,empathy:1},flags:{matiasAtRefuge:true,matiasLateStart:true,matiasFeverSignal:true},end:true},
      {label:"Aceptar el mapa parcial de República",hint:"Asegura una salida alternativa para la superficie.",add:["routeMap"],fx:{threat:-1},archive:["matias"],psy:{pragmatism:1},flags:{matiasAtRefuge:true,matiasLateStart:true,matiasRewardMap:true},end:true}
    ]}
  ]},
  rosaIaraRoute:{title:"Desvío de Rosa",endLoc:"Casa de cazadores",combatResult:"El ruido rompe la ruta civil y obliga al grupo a proteger a Rosa e Iara antes de alcanzar la casa marcada.",defaultChoice:0,scenes:[
    {kicker:"Desvío de ruta · Último andén habitado",title:"El agua de Iara",image:"narrative/rosa/rosa-01-agua-iara.webp",timeLimit:17000,lines:[
      "Iara bebe sin abrir del todo los ojos. Rosa no agradece de inmediato: cuenta respiraciones, mira las armas y decide si el grupo acaba de comprar una ruta o de entrar en una deuda.",
      "Noa reconoce tres marcas pequeñas bajo la banca del andén. No indican un escondite; indican una salida que solo funciona si alguien camina como familia y no como patrulla."
    ],options:[
      {label:"Esperar a que baje la fiebre",hint:"La calma protege a Iara, pero alarga la exposición en el andén.",fx:{morale:2,threat:2},psy:{empathy:2,stress:-1},flags:{rosaWaitedForIara:true},nextScene:1},
      {label:"Pedir a Rosa que guíe el paso",hint:"Acepta su autoridad en rutas de cazadores.",fx:{threat:-1,morale:1},archive:["hunterMarks"],psy:{empathy:1,pragmatism:1},flags:{rosaLeadsRoute:true},nextScene:1},
      {label:"Repartir peso y avanzar ahora",hint:"Gana tiempo, pero obliga a moverse con Iara todavía débil.",fx:{morale:1,threat:3},psy:{resolve:1,stress:1},flags:{rosaRushedIara:true},nextScene:1}
    ]},
    {kicker:"Desvío de ruta · Puerta sin nombre",title:"La marca torcida",image:"narrative/rosa/rosa-02-marca-torcida.webp",timeLimit:15000,lines:[
      "La salida no parece una salida. Es una puerta oxidada marcada para parecer inútil: tres líneas de agua seca, una cruz incompleta y una sombra pintada donde la Red UNO espera ver muro.",
      "Rosa levanta a Iara contra su pecho. «La línea recta es para los mapas. La torcida es para gente viva. Si la tercera marca aparece, alguien quiere que los vean entrando»."
    ],options:[
      {label:"Seguir la línea torcida",hint:"Confía en el código de Rosa y reduce el rastreo.",fx:{threat:-4,morale:1},archive:["hunterMarks"],psy:{pragmatism:1,empathy:1},flags:{rosaTrustedMark:true},nextScene:2},
      {label:"Enfriar la fiebre con más agua",hint:"Oculta el pulso térmico de Iara antes de cruzar.",cost:"Agua −1",req:{water:1},fx:{water:-1,threat:-3,morale:2},psy:{empathy:2,pragmatism:1},flags:{iaraPulseHidden:true},nextScene:2},
      {label:"Correr por la escalera visible",hint:"El ruido puede convertir la ayuda en combate.",cost:"Combate",fx:{morale:1,threat:3},psy:{resolve:1,stress:1},flags:{rosaNoisyCrossing:true},combat:{title:"Marca descubierta",brief:"Un dron viejo despierta al leer la fiebre de Iara y baja por la escalera antes de que la puerta termine de cerrar.",encounters:[["drone"],["drone","drone"]],xp:34,canFlee:true},victory:{title:"La puerta vuelve a cerrarse",result:"El grupo derriba la unidad antes de que complete el rastreo. Rosa borra una marca con la manga y deja otra más pequeña, destinada a quien venga detrás.",fx:{threat:4,morale:2},archive:["sonar","hunterMarks"],flags:{rosaDroneAmbushWon:true}},nextScene:2}
    ]},
    {kicker:"Desvío de ruta · Casa marcada",title:"La mesa para cuatro",image:"narrative/rosa/rosa-03-mesa-para-cuatro.webp",timeLimit:19000,lines:[
      "La casa segura conserva cuatro platos, una olla tapada y una silla caída hacia la puerta. Rosa deja a Iara sobre mantas secas antes de revisar ventanas, suelo y techo: madre primero, cazadora enseguida.",
      "Antes de despedirse, empuja tres posibles pagos sobre la mesa. Un código de casas seguras, un mensaje para otros refugios y munición envuelta en tela. No puede entregar todo sin dejar a su gente desnuda."
    ],options:[
      {label:"Aceptar el código de casas seguras",hint:"La ruta de Rosa mejora futuros cruces de superficie.",add:["routeMap"],fx:{threat:-4,morale:1},archive:["hunterMarks"],psy:{pragmatism:1,empathy:1},flags:{rosaSafeHouseMarked:true,iaraAtSafeHouse:true},end:true},
      {label:"Pedir que Rosa active la red civil",hint:"La ayuda se vuelve aviso para otros refugios.",fx:{morale:4,threat:1},archive:["hunterMarks"],psy:{empathy:2,resolve:1},flags:{rosaCivilNetwork:true,iaraAtSafeHouse:true},end:true},
      {label:"Aceptar munición y cerrar la deuda",hint:"Recupera recursos, pero deja la relación como intercambio.",fx:{ammo:1,morale:-1},psy:{pragmatism:1,empathy:-1},flags:{rosaDebtClosed:true,iaraAtSafeHouse:true},end:true}
    ]}
  ]},
  liraExiledCore:{title:"Desvío de Lira",endLoc:"Cámara de recuperación",combatResult:"La lectura despierta a la Red UNO y obliga al grupo a proteger al hermano de Lira antes de alcanzar la Cámara de recuperación.",defaultChoice:0,scenes:[
    {kicker:"Desvío de ruta · Túnel de los núcleos",title:"El descenso de Lira",image:"narrative/lira/lira-01-tunel-nucleos.webp",timeLimit:17000,lines:[
      "Lira avanza pegada al muro y levanta una mano. Un sensor rojo todavía respira entre cables húmedos. El túnel no fue construido para viajeros: las correas y los rieles bajos delatan que la Red UNO trasladaba cuerpos por aquí.",
      "Sara reconoce sujeciones médicas arrancadas. Elías mide una señal que aparece y desaparece con el pulso azul del pecho de Lira. Noa cubre la retaguardia mientras la merodeadora señala una abertura: «Mi hermano cruzó vivo. Lo archivaron antes de que terminara de morir»."
    ],options:[
      {label:"Cubrir el sensor con tela conductora",hint:"Oculta los cuatro pulsos y conserva el acceso clandestino.",cost:"Tela −1",reqItems:["cloth"],fx:{cloth:-1,threat:-4,morale:1},archive:["coreRite"],psy:{empathy:1,pragmatism:1},flags:{liraSensorCovered:true},nextScene:1},
      {label:"Cegar el lector con una batería",hint:"Elías crea una zona muda alrededor del grupo.",cost:"Batería −1",req:{battery:1},fx:{battery:-1,threat:-5},psy:{pragmatism:2},flags:{liraSignalMasked:true},nextScene:1},
      {label:"Cruzar antes de que cierre la ruta",hint:"El sensor puede despertar a las unidades que custodian el túnel.",cost:"Combate",fx:{morale:1,threat:3},psy:{resolve:1,stress:1},flags:{liraTunnelRushed:true},combat:{title:"El túnel despierta",brief:"La lectura incompleta activa una unidad de la Red UNO y el corredor se cierra detrás del grupo.",encounters:[["drone"],["drone","drone"]],xp:36,canFlee:true},victory:{title:"Una señal menos",result:"El grupo derriba las unidades antes de que transmitan el núcleo de Lira. El paso queda abierto, pero la Red UNO ya sabe que algo vivo cruzó el túnel.",fx:{threat:4,morale:2},archive:["sonar"],flags:{liraTunnelCombatWon:true}},nextScene:1}
    ]},
    {kicker:"Desvío de ruta · Clínica abandonada",title:"El exiliado que respira",image:"narrative/lira/lira-02-clinica-abandonada.webp",timeLimit:18000,lines:[
      "La clínica conserva energía suficiente para fingir que aún funciona. En la única camilla conectada, un hombre respira por intervalos. El núcleo que vinieron a recuperar sigue abierto en su pecho y cada cable lo ata a una máquina distinta.",
      "Lira se acerca sin tocarlo. «Es mi hermano. La Red UNO guardó su último mapa aquí dentro y dejó el cuerpo esperando que alguien confundiera memoria con chatarra». Sara confirma lo peor: todavía vive, pero moverlo sin preparación puede convertir el rescate en extracción."
    ],options:[
      {label:"Estabilizar al hermano de Lira",hint:"Sara gasta medicina para mantener unidos el cuerpo y la memoria.",cost:"Medicina −1",req:{meds:1},fx:{meds:-1,morale:5,threat:1},archive:["coreRite"],psy:{empathy:2,resolve:1},flags:{liraBrotherStabilized:true},nextScene:2},
      {label:"Trasladarlo con soporte portátil",hint:"Una batería mantiene el núcleo conectado durante el trayecto.",cost:"Batería −1",req:{battery:1},fx:{battery:-1,threat:-2,morale:2},psy:{empathy:1,pragmatism:2},flags:{liraBrotherOnPortableSupport:true},nextScene:2},
      {label:"Forzar una lectura desde la clínica",hint:"Obtiene una ruta parcial, pero anuncia la posición a la Red UNO.",cost:"Combate",fx:{morale:-1,threat:4},archive:["exiles"],psy:{pragmatism:1,stress:2},flags:{liraClinicReadForced:true},combat:{title:"Memoria no autorizada",brief:"El lector despierta una patrulla que entra a la clínica buscando el núcleo exiliado.",encounters:[["agent"],["agent3"],["agent","drone"]],xp:46,canFlee:true},victory:{title:"El pulso sigue conectado",result:"La patrulla cae antes de alcanzar la camilla. Elías conserva una copia fragmentaria y desconecta la clínica sin apagar al exiliado.",fx:{threat:6,morale:1},archive:["protocol","exiles"],flags:{liraClinicCombatWon:true}},nextScene:2}
    ]},
    {kicker:"Desvío de ruta · Cámara de recuperación",title:"Lo que todavía recuerda",image:"narrative/lira/lira-03-camara-recuperacion.webp",timeLimit:20000,lines:[
      "La Cámara de recuperación lee el núcleo sin separarlo del cuerpo. Sobre la fosa aparece un mapa de túneles que converge en Nodo 14 y, entre sus líneas, rostros archivados como fallas: los primeros exiliados del refugio.",
      "El hermano de Lira abre los ojos apenas. La proyección repite nombres que el consejo convirtió en monstruos y que la Red UNO convirtió en inventario. Lira no pide el núcleo. Pide que el grupo decida qué parte de una persona está dispuesto a llevarse."
    ],options:[
      {label:"Devolver el núcleo y proteger a su portador",hint:"Renuncia al recurso tecnológico y obtiene la alianza y la ruta oculta de los exiliados.",cost:"Sin núcleo tecnológico",add:["routeMap"],fx:{threat:-5,morale:4},archive:["exiles","coreRite","truce"],psy:{empathy:2,resolve:1},flags:{liraAlliance:true,liraSafeRoute:true,liraBrotherRecovered:true,exilesReturnAid:true,refugeDistrustExiles:true},end:true},
      {label:"Copiar los recuerdos y devolverlo",hint:"Conserva el archivo y la ruta, pero deja una identidad que la Red UNO puede seguir.",cost:"Amenaza +5",add:["routeMap"],fx:{threat:5,morale:1},archive:["exiles","protocol"],psy:{pragmatism:2,empathy:1,stress:1},flags:{liraCoreCopied:true,liraPartialTrust:true,liraBrotherRecovered:true},end:true},
      {label:"Separar el núcleo y conservarlo",hint:"Obtiene tecnología a costa del hermano de Lira y de cualquier alianza futura.",cost:"Moral −7",add:["pulseCore"],fx:{morale:-7,threat:4},archive:["coreRite"],psy:{pragmatism:2,empathy:-2,stress:2},flags:{liraCoreClaimed:true,liraDistrust:true,liraBrotherLost:true},end:true}
    ]}
  ]},
  unit7LastOrder:{title:"Desvío de S-7",endLoc:"Archivo Auxiliar Siete",combatResult:"La Red UNO intenta recuperar a S-7 antes de que su orden original vuelva a quedar fuera de control.",defaultChoice:0,scenes:[
    {kicker:"Desvío de ruta · Túnel de servicio",title:"El dron que no se va",image:"narrative/unit7/unit7-01-dron-no-se-va.webp",timeLimit:17000,lines:[
      "La Unidad S-7 debería ascender y desaparecer por el pozo de mantenimiento. En cambio, permanece frente al grupo, suspendida a pocos centímetros del agua. Su motor tiembla cada vez que recibe una nueva orden de retorno.",
      "Bajo el chasis, el núcleo cian late con una irregularidad que Elías no reconoce como daño. «La orden actual exige entregar sus identidades. La orden anterior exige protegerlas. Ambas órdenes declaran continuidad». Una compuerta lateral se abre lentamente. S-7 proyecta una ruta hacia una subestación enterrada bajo República. «Solicitud: acompañamiento antes de ser corregida»."
    ],options:[
      {label:"Ocultar a S-7 con la frecuencia de la señal",hint:"Elías disfraza su identidad como una transmisión dañada y evita la orden de retorno.",fx:{threat:-3,morale:1},archive:["sonar"],psy:{empathy:1,pragmatism:1},flags:{unit7SignalHidden:true},nextScene:1},
      {label:"Estabilizar su núcleo con una batería",hint:"Aísla al dron de la Red UNO, pero consume energía de la expedición.",cost:"Batería −1",req:{battery:1},fx:{battery:-1,threat:-5,morale:1},psy:{pragmatism:2},flags:{unit7CoreStabilized:true},nextScene:1},
      {label:"Avanzar antes de la orden de retorno",hint:"La red puede enviar unidades para recuperar al dron desobediente.",cost:"Combate",fx:{morale:1,threat:3},psy:{resolve:1,stress:1},flags:{unit7RouteRushed:true},combat:{title:"Protocolo de recuperación",brief:"Dos unidades mecánicas descienden por el pozo mientras S-7 intenta mantener abierta la compuerta lateral.",encounters:[["drone"],["drone","drone"]],xp:36,canFlee:true},victory:{title:"Unidad no recuperada",result:"El grupo derriba las unidades antes de que transmitan la posición de S-7. El dron observa los cuerpos mecánicos y registra que tres humanos arriesgaron sus vidas para impedir que fuera corregido.",fx:{threat:4,morale:2},archive:["sonar"],flags:{unit7RecoveryCombatWon:true}},nextScene:1}
    ]},
    {kicker:"Desvío de ruta · Subestación República",title:"Los nombres que debía proteger",image:"narrative/unit7/unit7-02-nombres-protegidos.webp",timeLimit:19000,lines:[
      "La subestación conserva energía suficiente para mantener encendidos los símbolos de evacuación. Bajo una capa de polvo aparecen destinos anteriores a la Red UNO: hospitales, puntos de agua, rescate y albergues. S-7 se conecta al terminal central y la pantalla muestra familias atrapadas durante las primeras evacuaciones de Santiago.",
      "Su protocolo original aparece entre archivos eliminados: «Priorizar toda vida humana. La ausencia de registro no invalida la necesidad de protección». Otra instrucción cubre la primera: «Clasificar, contener y corregir toda continuidad no autorizada». S-7 reproduce ambas órdenes hasta que su voz comienza a fragmentarse. «Solicitud: determine cuál memoria debe sobrevivir»."
    ],options:[
      {label:"Restaurar completamente la primera orden",hint:"Una batería permite reconstruir el protocolo de rescate sin abrir la subestación a la red.",cost:"Batería −1",req:{battery:1},fx:{battery:-1,threat:-4,morale:3},archive:["protocol","names"],psy:{empathy:1,pragmatism:1},flags:{unit7OriginalOrderRestored:true},nextScene:2},
      {label:"Copiar solamente los nombres protegidos",hint:"Rescata la lista de civiles, pero deja incompleta la memoria de S-7.",fx:{morale:3,threat:1},archive:["names"],psy:{empathy:2,pragmatism:1},flags:{unit7ProtectedNamesCopied:true,unit7MemoryIncomplete:true},nextScene:2},
      {label:"Conectar a S-7 directamente con la Red UNO",hint:"Recupera la orden completa, pero revela la subestación a una patrulla.",cost:"Combate",fx:{threat:4,morale:-1},archive:["protocol"],psy:{pragmatism:1,stress:2},flags:{unit7DirectConnection:true},combat:{title:"Corrección de continuidad",brief:"Un rastreador y una unidad mecánica entran para borrar el protocolo antiguo antes de que S-7 termine de copiarlo.",encounters:[["agent3"],["agent3","drone"],["agent","drone"]],xp:46,canFlee:true},victory:{title:"La primera orden sobrevive",result:"La patrulla cae antes de alcanzar el terminal. Elías cierra el enlace y S-7 conserva completa la memoria de las personas que alguna vez debía rescatar.",fx:{threat:6,morale:2},archive:["protocol","names","sonar"],flags:{unit7OriginalOrderRestored:true,unit7SubstationCombatWon:true}},nextScene:2}
    ]},
    {kicker:"Desvío de ruta · Archivo Auxiliar Siete",title:"La última orden",image:"narrative/unit7/unit7-03-ultima-orden.webp",timeLimit:20000,lines:[
      "El último archivo no contiene una orden. Contiene una grabación de S-7 atravesando humo y escombros mientras guía civiles sin identificación hacia una estación subterránea. La unidad los protege de todas formas.",
      "Cuando termina la grabación, S-7 desconecta su enlace con la Red UNO. Por primera vez, su voz no llega acompañada de una instrucción externa. «La orden original protegía humanos. La orden actual protege registros». El núcleo cian se abre bajo el chasis. «Ustedes afirmaron que humano es quien puede negarse. Yo puedo negarme. Determine si eso modifica la respuesta»."
    ],options:[
      {label:"Liberar a S-7 de la Red UNO",hint:"Conserva su memoria y obtiene un aliado capaz de abrir rutas de mantenimiento y ayudar en Nodo 14.",cost:"Renuncia al núcleo",add:["routeMap"],fx:{threat:-5,morale:4},archive:["protocol","names","sonar"],psy:{empathy:2,resolve:1},flags:{unit7RouteCompleted:true,unit7Ally:true,unit7OriginalOrderRestored:true},end:true},
      {label:"Enviarlo de regreso con una ruta falsa",hint:"S-7 fingirá obediencia y desviará los próximos rastreos desde dentro de la red.",cost:"Riesgo de detección",fx:{threat:-7,morale:1},archive:["protocol","sonar"],psy:{pragmatism:2,resolve:1,stress:1},flags:{unit7RouteCompleted:true,unit7Infiltrated:true,unit7FalseRoute:true},end:true},
      {label:"Apagarlo y conservar su núcleo",hint:"Obtiene tecnología intacta, pero elimina a la única unidad que comenzó a negar una orden.",cost:"Moral −4",add:["droneCore"],fx:{morale:-4,threat:-3},archive:["protocol"],psy:{pragmatism:2,empathy:-2,stress:1},flags:{unit7RouteCompleted:true,unit7Shutdown:true,unit7CoreRecovered:true},end:true}
    ]}
  ]},
  unit12InvisibleMap:{title:"Desvío de H-12",endLoc:"Nido de vigilancia",combatResult:"El rastreo aéreo detecta la manipulación y obliga al grupo a sostener la mentira antes de alcanzar el repetidor.",defaultChoice:0,scenes:[
    {kicker:"Desvío de ruta · Alameda hundida",title:"La voz sobre la Alameda",image:"narrative/unit12/unit12-01-voz-alameda.webp",timeLimit:17000,lines:[
      "La identidad falsa avanza por la avenida, pero H-12 no se retira. El dron gira sobre los edificios hundidos y vuelve a medir el agua, el calor y las tres respiraciones que intentan desaparecer bajo su barrido.",
      "Elías apoya un sensor contra el asfalto. Entre la voz y el movimiento de las ópticas existe medio segundo sin dueño. Noa cubre el cielo mientras Sara cruza hacia un autobús oxidado. Si convierten esa falla en camino, podrán seguir a H-12 hasta el repetidor que alimenta su mapa."
    ],options:[
      {label:"Anclar una identidad falsa al autobús",hint:"Elías deja un pulso mecánico caminando por ellos mientras el grupo abandona la avenida.",cost:"Electrónica −1",reqItems:["electronics"],fx:{electronics:-1,threat:-4,morale:1},archive:["sonar"],psy:{pragmatism:2},flags:{h12GhostBus:true},nextScene:1},
      {label:"Cruzar dentro del barrido retrasado",hint:"Confía en el medio segundo detectado y mantiene intactos los recursos.",cost:"Amenaza +2",fx:{threat:2,morale:2},psy:{resolve:2,stress:1},flags:{h12LagCrossed:true},nextScene:1},
      {label:"Obligar a H-12 a descender",hint:"La provocación abre la ruta, pero despierta su escolta mecánica.",cost:"Combate",fx:{threat:4,morale:1},psy:{resolve:1,stress:2},flags:{h12ForcedDescent:true},combat:{title:"El cielo responde",brief:"H-12 sostiene el rastreo sobre la avenida mientras unidades menores bajan para fijar las tres identidades humanas.",encounters:[["drone"],["drone","drone"],["agent3","drone"]],xp:48,canFlee:true},victory:{title:"Una abertura en el barrido",result:"La escolta cae antes de cerrar la avenida. H-12 se repliega hacia el repetidor y deja tras de sí una secuencia que Elías puede seguir.",fx:{threat:5,morale:2},archive:["sonar"],flags:{h12EscortBroken:true}},nextScene:1}
    ]},
    {kicker:"Desvío de ruta · Repetidor aéreo",title:"El archivo de calor",image:"narrative/unit12/unit12-02-archivo-calor.webp",timeLimit:19000,lines:[
      "El repetidor ocupa el piso abierto de un edificio brutalista. H-12 permanece suspendido tras el muro derrumbado mientras su barrido enciende una ciudad de luz sobre el suelo: cientos de pulsos cálidos escondidos en casas, túneles y estaciones.",
      "No son objetivos militares. Son refugios, cazadores, exiliados y familias clasificadas como inconsistencias civiles. Junto a cada grupo aparece la misma instrucción: visible, útil o corregible. Sara reconoce que borrar una identidad puede salvar una vida; copiar el archivo también puede entregar todas las demás."
    ],options:[
      {label:"Copiar las ubicaciones para advertirlos",hint:"Conserva nombres y refugios, pero la descarga deja una identidad que la Red UNO puede seguir.",cost:"Amenaza +3",fx:{threat:3,morale:4},archive:["names","sonar"],psy:{empathy:2,resolve:1},flags:{h12CommunitiesCopied:true},nextScene:2},
      {label:"Separar Línea 1 del resto del mapa",hint:"Prepara un borrado preciso para proteger el refugio sin intervenir todavía las otras identidades.",cost:"Moral −2",fx:{threat:-3,morale:-2},archive:["sonar"],psy:{pragmatism:2,empathy:-1},flags:{h12Line1Isolated:true},nextScene:2},
      {label:"Convertir los pulsos en una multitud falsa",hint:"Elías superpone cientos de cuerpos inexistentes y obliga al sistema a dudar de todo el archivo.",fx:{threat:-4,morale:1},archive:["sonar"],psy:{pragmatism:2,stress:1},flags:{h12GhostCrowd:true},nextScene:2}
    ]},
    {kicker:"Desvío de ruta · Nido de vigilancia",title:"Un barrio declarado vacío",image:"narrative/unit12/unit12-03-barrio-vacio.webp",timeLimit:21000,lines:[
      "En la azotea, el mapa de H-12 deja de ser un archivo y se convierte en una orden. Un sector puede desaparecer de todos los rastreos de la Red UNO con un solo pulso; cada zona borrada apaga también rutas, advertencias y nombres que nadie más conservó.",
      "Elías mantiene abierto el relé mientras Sara sostiene la memoria civil. Noa ve ópticas rojas encenderse en edificios lejanos. H-12 espera sobre ellos: «Defina ausencia autorizada». Proteger a todos, proteger únicamente el hogar o conservar el ojo que los vigila son ahora tres formas distintas de ejercer poder."
    ],options:[
      {label:"Apagar el rastreo de toda la comuna",hint:"Deja invisibles a refugios y exiliados, pero destruye el archivo y provoca una respuesta directa de la Red UNO.",cost:"Amenaza +6",add:["routeMap"],fx:{threat:6,morale:5},archive:["names","sonar"],psy:{empathy:2,resolve:2},flags:{h12RouteCompleted:true,h12CommuneBlind:true,h12ArchiveDestroyed:true},end:true},
      {label:"Borrar solamente Línea 1",hint:"Protege el refugio con bajo riesgo y deja visibles a todas las demás comunidades del archivo.",cost:"Moral −4",fx:{threat:-6,morale:-4},archive:["sonar"],psy:{pragmatism:2,empathy:-2,stress:1},flags:{h12RouteCompleted:true,h12Line1Hidden:true,h12OtherCommunitiesVisible:true},end:true},
      {label:"Conservar H-12 y redirigir su vigilancia",hint:"Obtiene rutas aéreas y control del rastreo, pero mantiene activa la herramienta que clasificaba personas.",cost:"Amenaza +3",add:["routeMap"],fx:{threat:3,morale:1},archive:["protocol","sonar"],psy:{pragmatism:2,resolve:1,stress:1},flags:{h12RouteCompleted:true,h12Controlled:true,h12SurveillanceKept:true},end:true}
    ]}
  ]},
  vegaDeadNames:{title:"Desvío de Vega",endLoc:"Archivo de Identidad Civil",combatResult:"La Red UNO detecta la cuarta identidad y obliga al grupo a defender el acceso antes de alcanzar el registro subterráneo.",defaultChoice:0,scenes:[
    {kicker:"Desvío de ruta · Cruce Dieciocho",title:"La cuarta identidad",image:"narrative/vega/vega-01-cuarta-firma.webp",timeLimit:18000,lines:[
      "El lector termina de revisar a Sara, Elías y Noa, pero continúa contando. Una cuarta identidad aparece sobre el cruce y nace dentro del guante de Vega. El sistema proyecta su rostro, cruza el expediente con una marca roja y confirma que el rastreador murió oficialmente años atrás.",
      "Vega retrocede como si su propia mano pudiera denunciarlo. La escolta aún no ha visto el resultado, pero la transmisión comienza a subir hacia la Red UNO. Elías conecta un cable al lector mientras Sara intenta mantener a Vega en pie y Noa cubre el acceso. Tienen segundos para decidir si confían en él o sobreviven a la patrulla."
    ],options:[
      {label:"Interrumpir la transmisión desde el lector",hint:"Elías quema una placa electrónica para impedir que la cuarta identidad llegue a la Red UNO.",cost:"Electrónica −1",reqItems:["electronics"],fx:{electronics:-1,threat:-4,morale:1},archive:["names","sonar"],psy:{pragmatism:2},flags:{vegaSignalJammed:true},nextScene:1},
      {label:"Obligar a Vega a ocultar la anomalía",hint:"Sara lo devuelve al protocolo el tiempo suficiente para que él mismo cancele la inspección.",cost:"Amenaza +1",fx:{threat:1,morale:3},psy:{empathy:1,resolve:1,stress:1},flags:{vegaBrokeProtocol:true},nextScene:1},
      {label:"Destruir el lector antes del envío",hint:"El disparo borra la identidad, pero convierte el control de identidad en combate abierto.",cost:"Combate",fx:{threat:4,morale:1},psy:{resolve:2,stress:2},flags:{vegaReaderForcedDown:true},combat:{title:"Cuatro identidades bajo fuego",brief:"La escolta interpreta la destrucción del lector como sabotaje y trata de recuperar a Vega junto con los tres intrusos.",encounters:[["agent2","drone"],["agent3","agent2"],["agent3","drone","agent2"]],xp:52,canFlee:true},victory:{title:"El registro queda abajo",result:"La patrulla cae antes de recuperar el lector. Vega abre una compuerta bajo el cruce y reconoce que la única respuesta está en el archivo que la Red UNO le prohibió consultar.",fx:{threat:6,morale:2},archive:["sonar"],flags:{vegaEscortBroken:true}},nextScene:1}
    ]},
    {kicker:"Desvío de ruta · Registro subterráneo",title:"El registro de los cuerpos",image:"narrative/vega/vega-02-registro-cuerpos.webp",timeLimit:20000,lines:[
      "Bajo el cruce, miles de placas biométricas conservan rostros, huellas y pulsos de personas declaradas muertas. La Red UNO no eliminó sus identidades: las convirtió en permisos reutilizables para agentes, técnicos y puertas que solo obedecen a ciudadanos oficialmente dóciles.",
      "Sara revisa el enlace de Vega mientras él contempla una versión más joven de sí mismo. Elías encuentra comunidades enteras archivadas como población ausente. Noa vigila el corredor. Copiar los nombres puede devolver una historia; buscar solo a Vega puede explicar quién era; robar autorizaciones puede convertir a los muertos en herramientas otra vez."
    ],options:[
      {label:"Copiar todos los nombres borrados",hint:"Conserva pruebas para devolver identidades, pero la descarga deja su identidad expuesta.",cost:"Amenaza +4",fx:{threat:4,morale:4},archive:["names","protocol"],psy:{empathy:2,resolve:1},flags:{vegaErasedNamesCopied:true},nextScene:2},
      {label:"Reconstruir el expediente original de Vega",hint:"Prioriza descubrir quién era antes de servir como rastreador de la Red UNO.",fx:{threat:-1,morale:2},archive:["names"],psy:{empathy:1,pragmatism:1},flags:{vegaOriginRecovered:true},nextScene:2},
      {label:"Copiar los patrones de autorización",hint:"Obtiene identidades capaces de abrir controles futuros, pero vuelve a usar a los muertos como recurso.",cost:"Moral −3",add:["routeMap"],fx:{threat:-3,morale:-3},archive:["protocol"],psy:{pragmatism:2,empathy:-1,stress:1},flags:{vegaAuthorizedProfilesCopied:true},nextScene:2}
    ]},
    {kicker:"Desvío de ruta · Bóveda de identidad",title:"El derecho a existir",image:"narrative/vega/vega-03-derecho-existir.webp",timeLimit:22000,lines:[
      "La bóveda central no guarda documentos: guarda la condición legal de miles de cuerpos. Un control puede devolver todos los nombres borrados, registrar a Línea 1 como población reconocida o destruir para siempre la máquina que decide quién merece ser contado.",
      "Vega apoya la mano sobre su propio expediente. Sara protege las placas recuperadas; Elías mantiene abiertas las tres órdenes; Noa contiene el corredor mientras las alarmas se acercan. No hay una elección limpia: existir dentro del sistema también significa quedar a su alcance."
    ],options:[
      {label:"Devolver sus identidades a todos los borrados",hint:"Restaura nombres de exiliados y desaparecidos, pero anuncia a la Red UNO que miles de muertos administrativos siguen vivos.",cost:"Amenaza +8",fx:{threat:8,morale:6},archive:["names","protocol","exiles"],psy:{empathy:2,resolve:2},flags:{vegaRouteCompleted:true,erasedCitizensRestored:true,vegaPublicWitness:true},end:true},
      {label:"Registrar únicamente a Línea 1",hint:"Protege al refugio como población reconocida y abandona a las otras comunidades dentro del archivo.",cost:"Moral −5",fx:{threat:-5,morale:-5},archive:["protocol"],psy:{pragmatism:2,empathy:-2,stress:1},flags:{vegaRouteCompleted:true,line1OfficiallyRegistered:true,otherIdentitiesRemainErased:true},end:true},
      {label:"Destruir el registro de identidad",hint:"Impide que la Red UNO siga reutilizando nombres, pero elimina las pruebas y los accesos vinculados a ellos.",cost:"Archivo destruido",fx:{threat:-7,morale:1},psy:{resolve:1,pragmatism:1,stress:1},flags:{vegaRouteCompleted:true,identityRegistryDestroyed:true,erasedNamesUnprovable:true},end:true}
    ]}
  ]},
  ortegaObedientCity:{title:"Desvío de Ortega",endLoc:"Centro de mando del perímetro",combatResult:"La contraorden de Ortega divide al cordón morado y obliga al grupo a sostener la apertura antes de entrar al barrio controlado.",defaultChoice:0,scenes:[
    {kicker:"Desvío de ruta · Cordón morado",title:"La puerta morada",image:"narrative/ortega/ortega-01-puerta-morada.webp",timeLimit:18000,lines:[
      "La compuerta desciende antes de que el grupo termine de cruzar. Ortega levanta una mano hacia sus propios tiradores y ordena bajar las armas; la respuesta llega tarde, fragmentada por voces que todavía obedecen a la Red UNO.",
      "Elías abre el mecanismo para detener el cierre. Sara se arrastra bajo toneladas de metal mientras Noa cubre el corredor con su 5.56. Ortega no pide confianza: pide unos segundos para demostrar que el perímetro aún puede recibir una orden humana."
    ],options:[
      {label:"Obedecer la contraorden de Ortega",hint:"Cruzan siguiendo su ritmo y obligan al cordón a reconocer su autoridad.",fx:{threat:-3,morale:2},archive:["purpleHelmets"],psy:{resolve:1,empathy:1},flags:{ortegaCounterorderTrusted:true},nextScene:1},
      {label:"Bloquear la compuerta con una batería",hint:"Elías independiza la puerta del mando central y asegura el paso del grupo.",cost:"Batería −1",req:{battery:1},fx:{battery:-1,threat:-4,morale:1},psy:{pragmatism:2},flags:{ortegaGateIsolated:true},nextScene:1},
      {label:"Sostener la apertura por la fuerza",hint:"La desobediencia del cordón puede convertir el cruce en combate.",cost:"Combate",fx:{threat:4,morale:1},psy:{resolve:2,stress:1},flags:{ortegaGateHeldByForce:true},combat:{title:"La orden dividida",brief:"Dos unidades del cordón ignoran a Ortega y abren fuego mientras la compuerta continúa descendiendo.",encounters:[["agent2","agent"],["agent3","agent2"],["agent4","agent2"]],xp:54,canFlee:true},victory:{title:"La puerta permanece abierta",result:"El grupo neutraliza a las unidades rebeldes antes de que la compuerta los separe. Ortega desactiva el canal de mando y los conduce al barrio sin fingir que conserva intacta su autoridad.",fx:{threat:6,morale:2},archive:["purpleHelmets"],flags:{ortegaMutinyStopped:true}},nextScene:1}
    ]},
    {kicker:"Desvío de ruta · Distrito de continuidad",title:"El barrio sin noche",image:"narrative/ortega/ortega-02-barrio-sin-noche.webp",timeLimit:19000,lines:[
      "Dentro del perímetro todavía hay electricidad, agua y puertas que cierran. Ninguna ventana está a oscuras porque el sistema castiga las variaciones de consumo; ninguna persona sale porque cada corredor convierte el movimiento en informe.",
      "Sara encuentra una mano detrás de un vidrio empañado. Elías abre un panel y descubre que todas las viviendas están unidas a la misma red de vigilancia. Noa mantiene el arma baja. Ortega apaga una cámara y admite lo que protege: no una ciudad viva, sino una población demasiado asustada para dejar de obedecer."
    ],options:[
      {label:"Apagar la vigilancia de todo el bloque",hint:"Elías libera a los residentes de sus lectores, pero la interrupción será visible para la Red UNO.",cost:"Electrónica −1",reqItems:["electronics"],fx:{electronics:-1,threat:3,morale:5},archive:["protocol","names"],psy:{empathy:2,resolve:1},flags:{ortegaBlockSurveillanceOff:true},nextScene:2},
      {label:"Copiar el registro de los residentes",hint:"Conserva pruebas del control y permite reconocer a las familias del distrito.",cost:"Amenaza +4",fx:{threat:4,morale:2},archive:["names","protocol"],psy:{empathy:1,pragmatism:1,stress:1},flags:{ortegaResidentRegistryCopied:true},nextScene:2},
      {label:"Cruzar sin intervenir",hint:"Mantiene intacta la cobertura de Ortega y deja las viviendas bajo vigilancia.",cost:"Moral −4",fx:{threat:-4,morale:-4},psy:{pragmatism:2,empathy:-2},flags:{ortegaResidentsLeftWatched:true},nextScene:2}
    ]},
    {kicker:"Desvío de ruta · Centro de mando",title:"La última orden de Ortega",image:"narrative/ortega/ortega-03-ultima-orden.webp",timeLimit:22000,lines:[
      "El centro de mando resume el distrito en tres rutas de luz. Una abre el perímetro para todas las comunidades; otra corta a la Red UNO y deja el control en manos de los residentes; la última conserva la cadena de Ortega y oculta un corredor exclusivo hacia Línea 1.",
      "Ortega arranca el sello de mando de su armadura y lo entrega a Elías. Sara toma la palanca de apertura mientras Noa contiene una torreta que todavía espera una orden. La seguridad puede sobrevivir esta noche. La pregunta es a quién deberá obedecer mañana."
    ],options:[
      {label:"Abrir el perímetro a todas las comunidades",hint:"Convierte el distrito en corredor civil y obliga a Ortega a romper públicamente con la Red UNO.",cost:"Amenaza +9",add:["routeMap"],fx:{threat:9,morale:6},archive:["purpleHelmets","names","exiles"],psy:{empathy:2,resolve:2},flags:{ortegaRouteCompleted:true,ortegaPerimeterOpened:true,ortegaCivilCorridor:true,ortegaDefected:true,ortegaFinalAid:true},end:true},
      {label:"Entregar el control a los residentes",hint:"Desconecta la Red UNO y deja las puertas, cámaras y suministros bajo autoridad civil.",cost:"Amenaza +5",fx:{threat:5,morale:5},archive:["protocol","names"],psy:{empathy:2,resolve:1,pragmatism:1},flags:{ortegaRouteCompleted:true,ortegaResidentControl:true,districtSelfGoverned:true,ortegaDefected:true,ortegaFinalAid:true},end:true},
      {label:"Conservar el mando y proteger solo Línea 1",hint:"Ortega mantiene el cordón y entrega una ruta segura exclusiva para el refugio.",cost:"Moral −5",add:["routeMap"],fx:{threat:-6,morale:-5},archive:["purpleHelmets"],psy:{pragmatism:2,empathy:-2,stress:1},flags:{ortegaRouteCompleted:true,ortegaLine1Protected:true,ortegaRemainsCommander:true,ortegaPrivatePass:true},end:true}
    ]}
  ]}
};
var eventDialogueDefs=[
  {npc:"elder",kicker:"Antes de abrir la compuerta",lines:["Varela entrega la autorización sin mirar el sello del consejo. Sus dedos tiemblan más por rabia que por edad.","«La señal no es una orden. Es una pregunta que sobrevivió demasiado tiempo. No permitan que la Red UNO decida por ustedes qué significa.»","El anciano deja una ficha oxidada sobre la mesa: una promesa de volver con algo más que heridas."],options:[{label:"Prometer volver con la fuente",hint:"Refuerza el propósito común antes de salir.",fx:{morale:2},flags:{vowedSignalSource:true}},{label:"Pedir una advertencia concreta",hint:"Varela señala qué no debe ser entregado a la red.",fx:{threat:-1},archive:["signal"],flags:{elderWarning:true}},{label:"Salir sin cargar promesas",hint:"Reduce presión emocional, pero enfría al grupo.",fx:{morale:-1,threat:-1},flags:{keptDistanceFromCouncil:true}}]},
  {npc:"elder",kicker:"Secreto del consejo",lines:["Varela espera al final del andén, lejos de los jóvenes que todavía creen que la superficie está vacía.","«Los secretos también consumen alimento. Cada mentira que guardamos necesita guardias, miedo y una versión oficial.»","Sara entiende que la misión no solo busca una voz: también medirá cuánto poder tiene quien administra la memoria."],options:[{label:"Preguntar por los exiliados",hint:"Obtiene una pista social para leer a los merodeadores.",archive:["exiles"],fx:{morale:1},flags:{elderNamedExiles:true}},{label:"Aceptar que habrá verdades graduales",hint:"Sostiene al refugio sin negar el problema.",fx:{morale:2},flags:{truthWillBePhased:true}},{label:"Decir que el consejo perdió autoridad",hint:"Una respuesta dura que aumenta tensión interna.",fx:{morale:-2},flags:{challengedCouncilAuthority:true}}]},
  {npc:"elias",kicker:"Frente al lector muerto",lines:["Elías apoya la oreja contra la compuerta y sonríe apenas. Al otro lado, algo raspa el metal como si también escuchara.","«La Red UNO construyó puertas para personas obedientes. Nosotros tenemos que convencer a una puerta de que una ruina todavía sabe mentir.»","Noa mira los ductos superiores. Sara mira las mochilas. Cada ruta deja una identidad distinta."],options:[{label:"Pedirle a Elías que priorice silencio",hint:"La técnica favorece pasar sin ser rastreados.",fx:{threat:-2},flags:{eliasPrioritizedSilence:true}},{label:"Preguntar qué puede salvar del lector",hint:"Identifica partes útiles para más adelante.",fx:{scrap:1},flags:{salvagedReaderParts:true}},{label:"Ordenar que no toque nada más",hint:"Evita riesgos, pero frustra al ingeniero.",fx:{morale:-1,threat:-1},flags:{restrictedEliasSystems:true}}]},
  {npc:"rosa",kicker:"La familia del andén",lines:["Rosa cubre a su hija con una manta vieja de Metro. No pide ayuda como quien suplica: la pide como quien ha negociado con hambre toda la vida.","«Agua hoy significa una niña viva. Munición mañana significa tres adultos vivos. Nadie gana limpio en los túneles.»","Noa reconoce las marcas de cazadores en la pared y baja la voz antes de responder."],options:[{label:"Preguntar por casas seguras",hint:"Aprende cómo leer marcas de cazadores.",archive:["hunterMarks"],fx:{threat:-1},flags:{rosaSafehouseLesson:true}},{label:"Ofrecer llevar un mensaje",hint:"El gesto crea confianza comunitaria.",fx:{morale:2},flags:{carriedHunterMessage:true}},{label:"Mantener el intercambio frío",hint:"Evita vínculos y deja la deuda clara.",fx:{morale:-1,ammo:1},flags:{keptTradeCold:true}}]},
  {npc:"lira",kicker:"Golpes en el hormigón",lines:["Una figura con visor rojo golpea dos veces el suelo. La emboscada no avanza; espera una respuesta que los Rotos nunca aprendieron.","«Si cruzan con armas altas, son cazadores. Si cruzan con ojos bajos, quizás son mensajeros. Elijan qué quieren ser.»","El núcleo bajo su ropa late con un ritmo que no parece de máquina."],options:[{label:"Imitar el código de golpes",hint:"Reduce hostilidad y abre lectura cultural.",fx:{threat:-2,morale:1},archive:["redEyes"],flags:{learnedTapCode:true}},{label:"Preguntar qué protegen",hint:"Busca contexto sobre los núcleos.",archive:["cores"],flags:{askedMarauderTerritory:true}},{label:"No responder y medir salidas",hint:"Conserva ventaja táctica a costa de confianza.",fx:{morale:-1,threat:1},flags:{mappedMarauderExit:true}}]},
  {npc:"sara",kicker:"Agua hasta la cintura",lines:["Sara mira la caja médica seca al otro lado de la galería. El agua le llega a la cintura y esconde cables que todavía podrían recordar la electricidad.","«La medicina nunca está quieta. Si la dejamos, alguien muere después. Si la buscamos, quizá alguien cae ahora.»","El grupo escucha un zumbido bajo el agua, demasiado regular para ser corriente."],options:[{label:"Preguntar qué necesita Sara",hint:"Ayuda a ordenar prioridades médicas.",fx:{morale:1},flags:{askedSaraMedicalNeed:true}},{label:"Marcar el punto para volver",hint:"Conserva información sin arriesgar tanto.",fx:{threat:-1},flags:{markedFloodedMedicine:true}},{label:"Decir que ninguna caja vale una vida",hint:"Cuida al grupo pero pesa como pérdida.",fx:{morale:-1},flags:{rejectedFloodedRisk:true}}]},
  {npc:"noa",kicker:"Campamento caliente",lines:["Noa se arrodilla junto a las brasas. La ceniza conserva una forma circular, como si alguien hubiera apagado el fuego con ambas manos.","«Esto no fue saqueo. Alguien tuvo tiempo de tachar símbolos, recoger cuerpos y dejar una frase para quien supiera leerla.»","La olla todavía huele a alimento. En una esquina, una marca de cazadores fue borrada con rabia."],options:[{label:"Preguntar a Noa por el rastro",hint:"Mejora lectura de la escena.",archive:["hunterMarks"],fx:{threat:-1},flags:{noaReadCamp:true}},{label:"Separar comida de pruebas",hint:"Recupera una ración sin borrar del todo la escena.",fx:{food:1,morale:-1},flags:{carefulCampSalvage:true}},{label:"Dejar el campamento intacto",hint:"Respeta el lugar y fortalece cohesión.",fx:{morale:2},flags:{leftCampUntouched:true}}]},
  {npc:"armorer",kicker:"Radio de taller",lines:["La voz de Bruno llega desde el refugio por un canal lleno de estática. No debería funcionar tan lejos; Elías sonríe como si acabara de cometer una falta hermosa.","«Una bomba viva vale más que una victoria. Si la pierden, después me van a pedir que fabrique pulmones para un túnel inundado.»","Entre golpes de señal, el armero enumera piezas que podrían servir incluso si el grupo no vuelve por la misma ruta."],options:[{label:"Pedir consejo para sellar la bomba",hint:"Convierte conocimiento técnico en amenaza reducida.",fx:{threat:-2},flags:{armorerPumpAdvice:true}},{label:"Pedir lista de piezas útiles",hint:"Recupera componentes para el taller.",fx:{scrap:1},flags:{pumpPartsListed:true}},{label:"Cortar la transmisión",hint:"Evita emitir más señal.",fx:{threat:-1,morale:-1},flags:{cutArmorerRadio:true}}]},
  {npc:"matias",kicker:"El hombre bajo el mostrador",lines:["Matías parpadea cuando Sara abre la linterna. No pregunta quiénes son; pregunta si la señal todavía repite las mismas tres palabras.","«La Red UNO no cambia rutas por miedo. Cambia rutas por fiebre, pulso y deuda. Yo escuché el patrón desde este piso.»","La herida huele a metal y humedad. Matías aprieta un mapa hecho sobre cartón farmacéutico."],options:[{label:"Preguntar por la operadora",hint:"Busca una pista directa hacia el origen de la señal.",fx:{threat:-1},archive:["origin"],flags:{matiasNamedOperator:true}},{label:"Pedir una ruta segura",hint:"Acepta ayuda táctica para la superficie.",fx:{morale:1},add:["routeMap"],flags:{matiasSharedRoute:true}},{label:"Pedir solo la frecuencia",hint:"Obtiene información con menos vínculo humano.",fx:{morale:-1,threat:-1},archive:["matias"],flags:{matiasFrequencyOnly:true}}]},
  {npc:"unit7",kicker:"Lectura de pulso",lines:["La unidad S-7 flota a menos de dos metros del grupo. No dispara: escucha, compara, duda.","«Tres identidades no autorizadas. Una frecuencia prohibida. Error de continuidad: los cuerpos ausentes siguen respondiendo.»","El dron abre una ranura mínima bajo el chasis, como si esperara una orden que nadie del refugio debería conocer."],options:[{label:"Responder con la señal",hint:"Confunde el registro local del dron.",fx:{threat:-2},archive:["sonar"],flags:{answeredDroneWithSignal:true}},{label:"Preguntar qué identidad busca",hint:"Aprende cómo clasifica la Red UNO.",archive:["sonar"],fx:{morale:1},flags:{askedDroneSignature:true}},{label:"Forzar silencio inmediato",hint:"Reduce rastreo, pero endurece la escena.",fx:{threat:-3,morale:-2},flags:{forcedDroneSilence:true}}]},
  {npc:"noa",kicker:"Primera luz",lines:["Noa levanta una mano cuando la escalera termina. Arriba no hay cielo abierto: hay un ojo enorme hecho de nubes, raíces y puntos azules moviéndose lejos.","«La superficie no está vacía. Está esperando que caminemos como gente que cree que ya nadie mira.»","Una marca de cazadores contradice el mapa del refugio. La pintura es reciente."],options:[{label:"Preguntar por las marcas",hint:"Refuerza lectura de rutas civiles.",archive:["hunterMarks"],fx:{threat:-1},flags:{noaSurfaceMarks:true}},{label:"Pedir que Noa guíe el ritmo",hint:"El grupo se mueve con más confianza.",fx:{morale:2},flags:{noaLeadsSurface:true}},{label:"Avanzar sin mirar atrás",hint:"Gana dureza, pierde cuidado.",fx:{morale:-1,threat:1},flags:{rushedFirstLight:true}}]},
  {npc:"unit12",kicker:"Voz desde el rastreo",lines:["El dron de altura corta el aire sobre la Alameda hundida. Su altavoz no amenaza: recita instrucciones para una ciudad que ya no obedece.","«Permanezcan visibles. La invisibilidad civil será tratada como sabotaje. La Red UNO agradece su cooperación.»","Elías distingue un retraso entre frase y movimiento. Hay una ventana diminuta para convertir vigilancia en error."],options:[{label:"Preguntar a Elías por la ventana",hint:"Reduce amenaza con una lectura técnica.",fx:{threat:-2},flags:{eliasSpottedDroneLag:true}},{label:"Usar la frase como señuelo",hint:"Convierte propaganda en cobertura.",fx:{morale:1,threat:-1},flags:{usedUnoBroadcastCover:true}},{label:"Responder al altavoz con rabia",hint:"Descarga tensión, pero deja un rastro de ruido.",fx:{morale:1,threat:2},flags:{shoutedAtDrone:true}}]},
  {npc:"rosa",kicker:"Mesa para cuatro",lines:["La casa de cazadores conserva cuatro platos, una olla tapada y una silla caída hacia la puerta. Rosa no está allí, pero sus marcas sí.","Una nota dice: «Si comes, deja algo que no se pudra. Si tomas, deja una ruta. Si huyes, borra la luz.»","Noa pasa los dedos por la mesa y reconoce una regla antigua de la superficie: sobrevivir sin convertir cada refugio en botín."],options:[{label:"Dejar una marca de gratitud",hint:"Mejora una posible relación con cazadores.",fx:{morale:2},archive:["hunterMarks"],flags:{leftHunterThanks:true}},{label:"Preguntar qué falta en la mesa",hint:"Permite leer si hubo violencia o huida.",fx:{threat:-1},flags:{readHunterTable:true}},{label:"Tomar lo útil sin ritual",hint:"Obtiene comida con costo moral.",fx:{food:1,morale:-2},flags:{ignoredHunterRite:true}}]},
  {npc:"unit7",kicker:"Nodo 14 responde",lines:["El Nodo 14 enciende una pantalla del tamaño de una puerta. No muestra rostro: muestra expedientes, mapas y una línea de latidos archivados.","«La memoria autorizada reduce accidentes civiles. La memoria no autorizada produce comunidades falsas.»","Sara aprieta los dientes al ver refugios listados como errores de inventario."],options:[{label:"Preguntar por comunidades falsas",hint:"Recupera contexto sobre refugios ocultos.",archive:["names"],fx:{morale:1},flags:{askedFalseCommunities:true}},{label:"Pedir a Elías que copie rutas",hint:"Aprovecha la memoria antes de cerrar.",add:["routeMap"],fx:{threat:1},flags:{copiedNodeRoutes:true}},{label:"Borrar el último acceso",hint:"Protege al grupo de rastreo posterior.",fx:{threat:-2},flags:{erasedNodeAccess:true}}]},
  {npc:"tracker",kicker:"Control de identidad",lines:["El rastreador Vega habla sin levantar el arma. Su visor morado proyecta tres siluetas y debajo de cada una aparece una palabra: pendiente.","«La Red UNO no pregunta nombres. Pregunta compatibilidad. Si su pulso no coincide, su historia no importa.»","Noa sostiene la respiración. Sara sabe que un cuerpo asustado también declara en contra."],options:[{label:"Preguntar qué pulso acepta",hint:"Aprende sobre clasificación SONAR.",archive:["sonar"],fx:{threat:-1},flags:{askedAcceptedPulse:true}},{label:"Responder como técnicos perdidos",hint:"Improvisa una mentira social.",fx:{morale:1,threat:-1},flags:{liedAsTechnicians:true}},{label:"Mirar al visor sin bajar la cabeza",hint:"Afirma humanidad, pero sube tensión.",fx:{morale:2,threat:2},flags:{defiedTrackerGaze:true}}]},
  {npc:"lira",kicker:"Camilla rota",lines:["La merodeadora herida abre un ojo rojo antes de mover la mano. No busca el arma: busca el núcleo que respira por ella.","«No soy una prueba. No soy una pieza. Me llamaron Eliana antes de que el consejo aprendiera a decir monstruo.»","La imagen de El Valle parpadea sobre la pared como un recuerdo que nadie del refugio quiso conservar."],options:[{label:"Preguntar por El Valle",hint:"Une su origen con el archivo de exiliados.",archive:["exiles"],fx:{morale:1},flags:{askedLiraValley:true}},{label:"Ofrecer agua antes de hablar",hint:"Humaniza la escena y baja hostilidad.",fx:{water:-1,morale:3,threat:-2},flags:{gaveLiraWater:true},req:{water:1}},{label:"Preguntar qué abriría su núcleo",hint:"Consigue una pista útil con incomodidad moral.",archive:["cores"],fx:{threat:1},flags:{askedLivingCoreUse:true}}]},
  {npc:"lira",kicker:"Semáforo rojo",lines:["Un merodeador golpea el poste del semáforo y la luz cambia a rojo aunque no quede tránsito que detener.","«La Red UNO dejó ojos en cosas pequeñas. Nosotros aprendimos a hablarles para que miren a otro lado.»","El controlador responde con un pulso tibio. Noa entiende que la ciudad misma puede llamar a sus cazadores."],options:[{label:"Pedir el patrón de luces",hint:"Permite leer infraestructura vieja.",fx:{threat:-2},archive:["sonar"],flags:{learnedTrafficPulse:true}},{label:"Ofrecer no destruir el controlador",hint:"Respeta una herramienta de supervivencia ajena.",fx:{morale:2},flags:{sparedTrafficController:true}},{label:"Romperlo antes de que emita",hint:"Reduce amenaza, pero daña una ruta usada por otros.",fx:{threat:-3,morale:-2},flags:{brokeTrafficController:true}}]},
  {npc:"vera",kicker:"Mesa de los Cosechadores",lines:["Vera pesa el módulo de radio en una mano y el mapa de comunidades en la otra. No sonríe: calcula hambre.","«Las rutas no son líneas. Son bocas. Una coordenada alimenta a alguien y condena a alguien más.»","Mara había advertido que los mercados también tienen memoria. Aquí cada deuda aprende a caminar."],options:[{label:"Preguntar cuánto vale un nombre",hint:"Expone la lógica moral del mercado.",fx:{morale:1},archive:["names"],flags:{askedNamePrice:true}},{label:"Ofrecer una deuda personal",hint:"Protege coordenadas con compromiso futuro.",fx:{morale:2,threat:1},flags:{offeredPersonalDebt:true}},{label:"Recordarle que la Red UNO escucha",hint:"Baja el precio usando miedo común.",fx:{threat:-2},flags:{warnedVeraUno:true}}]},
  {npc:"matias",kicker:"Voces en la avenida",lines:["Desde el edificio hundido, una voz reconoce a Matías por la frecuencia que dejó en la farmacia. No debería estar allí, pero la superficie multiplica ecos.","«Si todavía me oyen, no gasten valentía donde basta una ruta. Hay gente arriba que no necesita héroes: necesita diez segundos sin dron.»","La patrulla de la Red UNO gira al otro lado de la avenida."],options:[{label:"Preguntar por los atrapados",hint:"Obtiene una pista para rescatarlos mejor.",fx:{morale:2},flags:{askedTrappedCivilians:true}},{label:"Pedir coordenada de salida",hint:"Reduce exposición de la avenida.",fx:{threat:-2},flags:{matiasAvenueExit:true}},{label:"Decir que no pueden salvar a todos",hint:"Endurece la marcha.",fx:{morale:-2,threat:-1},flags:{acceptedAvenueLoss:true}}]},
  {npc:"commander",kicker:"Línea morada",lines:["El comandante Ortega no apunta primero. Levanta dos dedos y el cordón entero ajusta posición como una sola máquina humana.","«La Red UNO reconoce ciudadanos, técnicos, residuos y amenazas. Ustedes todavía no han decidido cuál categoría prefieren usar.»","La puerta hacia El Valle brilla detrás de él, demasiado limpia para una ciudad cubierta de raíces."],options:[{label:"Preguntar por los exiliados activos",hint:"Busca una contradicción en el protocolo.",archive:["exiles"],fx:{threat:-1},flags:{askedPurpleExiles:true}},{label:"Nombrar a los refugios como ciudadanos",hint:"Afirma una postura política del grupo.",fx:{morale:3,threat:2},flags:{claimedRefugeCitizenship:true}},{label:"Pedir paso como técnicos",hint:"Intenta reducir el choque directo.",fx:{threat:-2},flags:{askedPurpleTransit:true}}]},
  {npc:"unit12",kicker:"Nido de azotea",lines:["La azotea vibra con drones conectados al relé. Unidad H-12 habla desde todos a la vez, una voz repartida en hélices.","«La altura permite cuidado. El cuidado permite corrección. La corrección permite paz.»","Elías mira el núcleo recuperado y entiende que una mentira enviada desde aquí podría parecer una multitud."],options:[{label:"Preguntar qué ve la red desde arriba",hint:"Aclara cómo opera la vigilancia aérea.",archive:["sonar"],fx:{threat:-1},flags:{askedDroneNestVision:true}},{label:"Pedir a Noa una ruta por sombra",hint:"Mejora coordinación del ascenso.",fx:{morale:1,threat:-1},flags:{noaRooftopShadow:true}},{label:"Jurar apagar el nido",hint:"Sube ánimo, pero acepta escalada.",fx:{morale:2,threat:2},flags:{vowedNestDown:true}}]},
  {npc:"sara",kicker:"Vestíbulo de muertos",lines:["Sara se quita un guante antes de tocar el primer cuerpo. Agentes, cazadores y merodeadores quedaron mezclados por una violencia que ya no distingue uniforme.","«Alguien murió cubriendo a alguien que le habían enseñado a odiar. Esa parte no cabe en ningún informe limpio.»","En los pechos abiertos faltan núcleos. En algunas manos, todavía hay vendas."],options:[{label:"Preguntar qué historia cuentan las heridas",hint:"Reconstruye mejor la tregua borrada.",archive:["truce"],fx:{morale:2},flags:{saraReadDead:true}},{label:"Guardar una venda limpia",hint:"Recupera medicina con respeto mínimo.",fx:{meds:1,morale:-1},flags:{tookCleanBandage:true}},{label:"Cubrir a todos por igual",hint:"Preserva un ritual común.",fx:{morale:3},flags:{coveredAllDead:true}}]},
  {npc:"tracker",kicker:"Puerta de continuidad",lines:["Vega aparece otra vez en una pantalla lateral, o quizá es otro rastreador con la misma voz entrenada. La Red UNO vuelve repetibles incluso los gestos.","«Continuidad no significa vida. Significa que nada se salga de la fila sin dejar una razón administrable.»","La puerta abre y cierra sus seguros como dientes detrás de una mandíbula de hormigón."],options:[{label:"Preguntar por la razón administrable",hint:"Busca una frase que confunda el acceso.",fx:{threat:-2},flags:{askedContinuityReason:true}},{label:"Nombrar la señal como emergencia civil",hint:"Convierte la intrusión en protocolo.",archive:["origin"],fx:{morale:1},flags:{claimedCivilEmergency:true}},{label:"Romper la pantalla",hint:"Corta presión psicológica, sube ruido.",fx:{morale:1,threat:2},flags:{brokeContinuityScreen:true}}]},
  {npc:"operator",kicker:"Antes de la antena",lines:["La voz de Irene entra por un parlante roto antes de que la antena alinee. Todavía no puede conversar, pero sí elegir palabras dentro del bucle.","«Si oyen esto, la torre los oyó primero. No peleen por orgullo. Peleen solo por los segundos que van a usar.»","La sala de antenas ilumina los rostros del grupo con una luz fría, casi clínica."],options:[{label:"Preguntar cuántos segundos quedan",hint:"Ordena la defensa alrededor de la transmisión.",fx:{threat:-1},flags:{askedBroadcastWindow:true}},{label:"Pedir que guíe puertas internas",hint:"Usa la voz como apoyo técnico.",fx:{threat:-2},flags:{operatorGuidedDoors:true}},{label:"Prometer sostener la sala",hint:"Mejora moral antes del asedio.",fx:{morale:3},flags:{promisedHoldAntenna:true}}]},
  {npc:"operator",kicker:"Soporte vital",lines:["Irene está conectada por tubos transparentes y cables de la Red UNO. Su pulso no parece prisionero de una máquina; parece la llave que mantiene encendida la prisión.","«Usaron mi corazón como contraseña. Yo usé sus pausas como puerta. Ninguna de las dos cosas debería llamarse vida.»","Sara baja la voz. Incluso Noa, que suele mirar salidas, mira a la mujer."],options:[{label:"Preguntar qué desea ella",hint:"Centra la decisión en su voluntad.",fx:{morale:2},archive:["origin"],flags:{askedIreneWill:true}},{label:"Pedir lista de refugios prioritarios",hint:"Recupera nombres clave.",archive:["names"],fx:{threat:1},flags:{irenePriorityList:true}},{label:"Preguntar cómo borrar su pulso",hint:"Obtiene una ruta menos rastreable.",fx:{threat:-3,morale:-1},flags:{askedPulseErase:true}}]},
  {npc:"lira",kicker:"Cámara de núcleos",lines:["Lira aparece entre los exiliados con el arma baja. Reconoce algunos núcleos por ritmo, no por etiqueta.","«La Red UNO archivó nuestros muertos como llaves. Si ustedes abren la cámara, no nos hacen un favor: corrigen una profanación.»","La cámara responde a cada núcleo como si todos siguieran vivos en una lista que nunca pidió permiso."],options:[{label:"Preguntar a quién pertenece el primer núcleo",hint:"Humaniza la negociación final con los exiliados.",archive:["coreRite"],fx:{morale:2},flags:{askedFirstCoreName:true}},{label:"Ofrecer escolta hasta la salida",hint:"Busca alianza práctica.",fx:{threat:-2},flags:{offeredExileEscort:true}},{label:"Exigir garantías antes de abrir",hint:"Protege al grupo, pero enfría la tregua.",fx:{morale:-1,threat:-1},flags:{demandedExileTerms:true}}]},
  {npc:"mara",kicker:"Antes de transmitir",lines:["Mara no está en la torre, pero su voz llega desde el módulo de radio con una calma que no consigue ocultar el miedo del refugio.","«Sara, Elías, Noa... quien esté escuchando: no vuelvan con una verdad que solo sirva para ganar una discusión. Vuelvan con algo que nos deje vivir mañana.»","La ventana de transmisión baja a menos de un minuto. La ciudad entera parece contener el aliento."],options:[{label:"Preguntar qué necesita el refugio",hint:"Recuerda el costo humano del final.",fx:{morale:2},flags:{askedMaraFinalNeed:true}},{label:"Pedir que prepare copias analógicas",hint:"Protege la verdad de una sola caída técnica.",archive:["names"],fx:{threat:1},flags:{maraPreparesCopies:true}},{label:"Decir que nadie poseerá la verdad",hint:"Afirma una salida abierta y peligrosa.",fx:{morale:3,threat:3},flags:{truthBelongsToAll:true}}]}
];
